INSERT INTO `categories` (`id`, `title`, `title_jp`, `slug`, `summary`, `summary_jp`, `photo`, `is_parent`, `parent_id`, `added_by`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Software Development & Engineering', 'ソフトウェア開発-エンジニアリング', 'software-development-engineering', 'The Software Development & Engineering category is designed for learners who want to build, maintain, and improve modern software systems. Courses in this category focus on practical programming skills, application development, and engineering best practices used in real-world professional environments. Learners progress from fundamental programming concepts to advanced system design, quality assurance, and scalable application development. This category is suitable for beginners entering the IT field as well as experienced professionals looking to deepen their technical expertise and align with industry standards.', 'ソフトウェア開発とエンジニアリングのカテゴリは、最新のソフトウェアシステムを構築、維持、改善したい学習者のために設計されています。 このカテゴリのコースでは、実践的なプログラミングスキル、アプリケーション開発、および現実世界の専門的な環境で使用されるエンジニ 学習者は、基本的なプログラミングの概念から高度なシステム設計、品質保証、スケーラブルなアプリケーション開発に進みます。 このカテゴリは、IT分野に参入する初心者だけでなく、彼らの技術的専門知識を深め、業界標準に合わせて探して経験豊富な専門家に適しています。', 'NULL', 1, NULL, NULL, 'active', NULL, NULL),
(2, 'Data, Automation & AI', 'データ、自動化、AI', 'data-automation-ai', 'The Data, Automation & AI category focuses on leveraging data and intelligent tools to improve productivity, decision-making, and operational efficiency. Courses in this category help learners understand how data is collected, analyzed, and applied in business and technical contexts. Learners also explore automation techniques and AI-powered tools that reduce manual work and enable smarter workflows. This category is suitable for both technical and non-technical professionals seeking to enhance their effectiveness through data-driven approaches.', 'データ、自動化、AIカテゴリでは、データとインテリジェントなツールを活用して、生産性、意思決定、および運用効率を向上させることに焦点を当てています。 このカテゴリのコースは、学習者がビジネスや技術の文脈でデータがどのように収集、分析、適用されるかを理解するのに役立ちます。 学習者はまた、手動作業を削減し、よりスマートなワークフローを可能にする自動化技術とAIを活用したツールについても学びます。 このカテゴリは、データ駆動型アプローチを通じてその有効性を強化しようとしている技術的および非技術的な専門家の両方に適しています。', 'NULL', 1, NULL, NULL, 'active', NULL, NULL),
(3, 'IT Infrastructure, Cloud & Security', 'ITインフラ、クラウド、セキュリティ', 'it-infrastructure-cloud-security', 'The IT Infrastructure, Cloud & Security category focuses on the systems and technologies that support reliable, secure, and scalable IT operations. Courses in this category help learners understand how servers, networks, cloud platforms, and security frameworks work together in modern environments. Learners progress from foundational infrastructure concepts to advanced cloud architectures, DevOps practices, and cybersecurity governance. This category is ideal for IT professionals, engineers, and managers responsible for system stability and risk management.', 'ITインフラストラクチャ、クラウド、セキュリティカテゴリは、信頼性、安全性、拡張性の高いIT運用をサポートするシステムと技術に焦点を当てています。 このカテゴリのコースは、学習者が最新の環境でサーバー、ネットワーク、クラウドプラットフォーム、およびセキュリティフレームワークがどのように連携するかを理解するのに役立ちます。 学習者は、基本的なインフラストラクチャの概念から、高度なクラウドアーキテクチャ、DevOpsプラクティス、サイバーセキュリティガバナンスに進みます。 このカテゴリは、システムの安定性とリスク管理を担当するITプロフェッショナル、エンジニア、マネージャーに最適です。', 'NULL', 1, NULL, NULL, 'active', NULL, NULL),
(4, 'Product Design, UX & Digital Experience', 'プロダクトデザイン、UX、デジタル体験', 'product-design-ux-digital-experience', 'This category focuses on designing meaningful digital products that deliver seamless and engaging user experiences. Learners explore user-centered design principles, interface strategy, usability optimization, and digital product thinking. The content supports professionals in creating intuitive, scalable, and value-driven digital experiences across web and mobile platforms.', 'このカテゴリでは、シームレスで魅力的なユーザーエクスペリエンスを提供する意味のあるデジタル製品の設計に焦点を当てています。 学習者は、ユーザー中心の設計原則、インターフェイス戦略、ユーザビリティの最適化、およびデジタル製品の思考を探ります。 コンテンツは、ウェブとモバイルプラットフォーム全体で直感的でスケーラブルで価値主導型のデジタルエクスペリエンスを作成する専門家をサポートしています。', 'NULL', 1, NULL, NULL, 'active', NULL, NULL),
(5, 'DevOps, Agile & Technology Leadership', 'DevOps、アジャイル、テクノロジーのリーダーシップ', 'devops-agile-technology-leadership', 'This category centers on modern technology practices that enable scalable development, operational efficiency, and high-performing teams. Learners gain insight into DevOps principles, Agile frameworks, automation strategies, and leadership approaches required to manage technical teams and drive continuous improvement in fast-evolving digital environments.', 'このカテゴリは、スケーラブルな開発、運用効率、高性能なチームを可能にする最新の技術慣行に焦点を当てています。 学習者の洞察力を得ることDevOps理の原則の枠組みアジャイル、オートメーション戦略、リーダーシップに必要な管理技術チームおよび駆動の継続的改善に進化するデジタル環境です。', 'NULL', 1, NULL, NULL, 'active', NULL, NULL);
