INSERT INTO `pages` (`id`, `page_title`, `page_title_ja`, `page_slug`, `page_desc`, `page_desc_ja`, `page_meta`, `page_keywords`) VALUES
(1, 'Refund & Cancellation Policy', '返金＆キャンセルポリシー', 'refund-policy', '<div class=\"contact-content\">\r\n  <div class=\"page-cntnt\">\r\n\r\n    <p class=\"mb-4\">\r\n      At <strong>LYPRO COMPANY LIMITED</strong>, we strive to provide a high-quality learning experience. This Refund Policy outlines the circumstances under which a refund may be approved, ensuring a fair and transparent process for all learners.\r\n    </p>\r\n\r\n    <h4 class=\"mt-4 mb-3\">Student Support First</h4>\r\n    <p class=\"mb-4\">\r\n      If you encounter any difficulties with your course, we encourage you to contact our support team before requesting a refund. Many issues can be resolved quickly. Please reach out to us at \r\n      <a href=\"mailto:contact@risebeyondgrowth.com\">contact@risebeyondgrowth.com</a>, and we will work to assist you promptly.\r\n    </p>\r\n\r\n    <h4 class=\"mt-4 mb-3\">Conditions for Refund Approval</h4>\r\n    <ul>\r\n      <li><strong>Request Within 14 Days:</strong> Refund requests must be submitted within 14 days from the original purchase date and include a reasonable explanation</li>\r\n      <li><strong>Unauthorized or Fraudulent Charges:</strong> Claims involving unauthorized transactions must be supported by appropriate evidence</li>\r\n      <li><strong>Unresolved Technical Problems:</strong> If verified access issues cannot be corrected within a reasonable timeframe</li>\r\n      <li><strong>Special Circumstances:</strong> Certain cases may be reviewed individually at our discretion</li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-4 mb-3\">Situations Where Refunds Will Not Be Issued</h4>\r\n    <ul>\r\n      <li><strong>Excessive or Repeated Requests:</strong> Abuse of the refund process may result in denial of future refund eligibility or purchasing privileges</li>\r\n      <li><strong>Breach of Terms:</strong> Any violation of our Terms of Service, including unauthorized distribution, resale, or misuse of course materials, voids refund eligibility</li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-4 mb-3\">Additional Information</h4>\r\n    <ul>\r\n      <li>This Refund Policy forms part of our overall Terms of Service</li>\r\n      <li>Eligibility is determined based on the purchase date, regardless of any subsequent account closure</li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-4 mb-3\">Contact & Assistance</h4>\r\n    <p class=\"mb-1\">\r\n      For refund inquiries or general questions, please contact us:\r\n    </p>\r\n    <p class=\"mb-0\">\r\n      <strong>Email:</strong> <a href=\"mailto:contact@risebeyondgrowth.com\">contact@risebeyondgrowth.com</a><br>\r\n      <strong>Typical Response Time:</strong> Within 2 business days\r\n    </p>\r\n\r\n  </div>\r\n</div>\r\n', '<div class=\"contact-content\">\r\n  <div class=\"page-cntnt\">\r\n\r\n    <p class=\"mb-4\">\r\n      <strong>LYPRO COMPANY LIMITED</strong>では、高品質な学習体験の提供に努めています。本返金ポリシーは、返金が承認される条件を明確にし、すべての受講者にとって公正かつ透明性のある対応を確保することを目的としています。\r\n    </p>\r\n\r\n    <h4 class=\"mt-4 mb-3\">まずはサポートへご相談ください</h4>\r\n    <p class=\"mb-4\">\r\n      コースに関して問題やご不明点がある場合は、返金申請を行う前にサポートチームまでご連絡ください。多くの問題は迅速に解決可能です。\r\n      <a href=\"mailto:contact@risebeyondgrowth.com\">contact@risebeyondgrowth.com</a> までご連絡いただければ、速やかに対応いたします。\r\n    </p>\r\n\r\n    <h4 class=\"mt-4 mb-3\">返金承認の条件</h4>\r\n    <ul>\r\n      <li><strong>14日以内の申請：</strong> 返金申請は購入日から14日以内に行い、合理的な理由を明記する必要があります</li>\r\n      <li><strong>不正または無断請求：</strong> 不正利用や無断取引に関する申請には、適切な証拠の提出が必要です</li>\r\n      <li><strong>未解決の技術的問題：</strong> 確認済みのアクセス障害が合理的な期間内に解決できない場合</li>\r\n      <li><strong>特別な事情：</strong> 個別の事情については、当社の裁量により検討される場合があります</li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-4 mb-3\">返金対象外となる場合</h4>\r\n    <ul>\r\n      <li><strong>過度または繰り返しの申請：</strong> 返金制度の不正利用が確認された場合、今後の返金や購入が制限されることがあります</li>\r\n      <li><strong>利用規約違反：</strong> コース教材の無断共有、再販売、再配布、その他の不正使用など、利用規約に違反した場合は返金対象外となります</li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-4 mb-3\">補足事項</h4>\r\n    <ul>\r\n      <li>本返金ポリシーは、当社の利用規約の一部を構成します</li>\r\n      <li>返金の可否は購入日を基準に判断され、後日アカウントが閉鎖された場合でも適用されます</li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-4 mb-3\">お問い合わせ</h4>\r\n    <p class=\"mb-1\">\r\n      返金に関するご質問やサポートが必要な場合は、以下までご連絡ください：\r\n    </p>\r\n    <p class=\"mb-0\">\r\n      <strong>メール：</strong> <a href=\"mailto:contact@risebeyondgrowth.com\">contact@risebeyondgrowth.com</a><br>\r\n      <strong>通常の回答時間：</strong> 2営業日以内\r\n    </p>\r\n\r\n  </div>\r\n</div>\r\n', NULL, NULL),
(2, 'Privacy Policy', '個人情報保護方針', 'privacy-policy', '<div class=\"contact-content\">\n  <div class=\"page-cntnt\">\n\n    <p class=\"mb-4\">\n      Protecting your privacy is important to us. This Privacy Policy explains how we collect, process, store, and safeguard both personal and non-personal information obtained through your use of our website.\n    </p>\n\n    <h4 class=\"mt-4 mb-3\">Personal Information: Collection & Purpose</h4>\n    <p>\n      You may access most areas of our website without submitting personal details. However, certain features may require you to provide specific information.\n    </p>\n    <p class=\"mb-3\">\n      We collect identifiable personal data only when:\n    </p>\n    <ul>\n      <li>You voluntarily provide it via forms (such as enrollment, inquiries, or subscriptions)</li>\n      <li>It is gathered through standard analytical tools during your interaction with our website</li>\n    </ul>\n    <p class=\"mb-3\">\n      Any personal information collected is processed securely and used solely for the intended and disclosed purposes. We do not trade, lease, or distribute your data to third parties, except:\n    </p>\n    <ul>\n      <li>When legally required (for example, through judicial orders or regulatory obligations)</li>\n      <li>When necessary to defend our rights or comply with applicable laws</li>\n    </ul>\n\n    <h4 class=\"mt-4 mb-3\">Non-Personal Data & Website Analytics</h4>\n    <p>\n      To maintain and enhance website performance, we may automatically collect general, non-identifiable information, including:\n    </p>\n    <ul>\n      <li>IP address</li>\n      <li>Browser specifications</li>\n      <li>Device type and operating system details</li>\n      <li>Access timestamps and referring web addresses</li>\n    </ul>\n    <p class=\"mb-4\">\n      This information is used strictly for analytical purposes, performance monitoring, and user experience improvements. We may engage reputable third-party analytics providers who are contractually required to uphold strict confidentiality and security standards.\n    </p>\n\n    <h4 class=\"mt-4 mb-3\">Use of Cookies</h4>\n    <p>\n      Our website utilizes cookies, which are small data files stored on your device, to optimize functionality and better understand user behavior. These cookies enable us to recognize returning visitors and tailor content accordingly.\n    </p>\n    <ul>\n      <li>Cookies do not retrieve personal data from your device without authorization</li>\n      <li>Most web browsers automatically accept cookies, though you may adjust your settings to disable them</li>\n      <li>Please note that disabling cookies may limit certain website features</li>\n    </ul>\n\n    <h4 class=\"mt-4 mb-3\">Third-Party Websites</h4>\n    <p class=\"mb-4\">\n      Our platform may contain links to independent third-party websites. We do not control or assume responsibility for their privacy policies or practices. We encourage you to review the privacy terms of any external sites you visit.\n    </p>\n\n    <h4 class=\"mt-4 mb-3\">Security Measures</h4>\n    <p class=\"mb-4\">\n      We apply reasonable technical safeguards and organizational procedures to protect your information against unauthorized access, misuse, or disclosure. Nonetheless, no digital system can guarantee absolute security. We cannot be held liable for breaches, interruptions, or losses arising from circumstances beyond our reasonable control.\n    </p>\n\n    <h4 class=\"mt-4 mb-3\">Updates and Modifications</h4>\n    <p class=\"mb-3\">\n      We reserve the right to modify this Privacy Policy from time to time. Any updates will be reflected on this page. Your continued use of the website following such changes indicates your acceptance of the revised terms.\n    </p>\n\n    <p class=\"mb-0\">\n      If you have any privacy-related inquiries or requests, please contact our support team. We aim to respond within two business days.\n    </p>\n\n  </div>\n</div>\n', '<div class=\"contact-content\">\n  <div class=\"page-cntnt\">\n\n    <p class=\"mb-4\">\n      当社は、お客様のプライバシー保護を重要視しています。本プライバシーポリシーでは、当ウェブサイトのご利用を通じて取得される個人情報および非個人情報の収集、処理、保管、ならびに保護の方法について説明します。\n    </p>\n\n    <h4 class=\"mt-4 mb-3\">個人情報：収集および利用目的</h4>\n    <p>\n      当ウェブサイトの大部分は、個人情報を提供することなく閲覧いただけます。ただし、一部の機能やサービスをご利用いただく際には、特定の情報の提供をお願いする場合があります。\n    </p>\n    <p class=\"mb-3\">\n      当社が個人を特定できる情報を収集するのは、以下の場合に限られます：\n    </p>\n    <ul>\n      <li>登録、問い合わせ、購読などのフォームを通じて、お客様が自発的に提供された場合</li>\n      <li>ウェブサイト利用時に標準的な分析ツールを通じて取得される場合</li>\n    </ul>\n    <p class=\"mb-3\">\n      収集された個人情報は、安全に管理され、明示された目的の範囲内でのみ使用されます。当社は、お客様の情報を第三者に販売、貸与、または提供することはありません。ただし、以下の場合を除きます：\n    </p>\n    <ul>\n      <li>法令に基づき開示が求められる場合（裁判所命令や法的義務など）</li>\n      <li>当社の権利を保護し、または法令を遵守するために必要な場合</li>\n    </ul>\n\n    <h4 class=\"mt-4 mb-3\">非個人情報およびウェブサイト分析</h4>\n    <p>\n      ウェブサイトの機能維持および向上のため、当社は以下のような個人を特定しない一般情報を自動的に収集する場合があります：\n    </p>\n    <ul>\n      <li>IPアドレス</li>\n      <li>ブラウザの種類および仕様</li>\n      <li>デバイスの種類およびオペレーティングシステム情報</li>\n      <li>アクセス日時および参照元URL</li>\n    </ul>\n    <p class=\"mb-4\">\n      これらの情報は、分析、パフォーマンス監視、ならびにユーザー体験の向上を目的としてのみ使用されます。また、当社は信頼できる第三者の分析サービス提供者と連携する場合がありますが、これらの提供者は厳格な機密保持および情報保護義務を負っています。\n    </p>\n\n    <h4 class=\"mt-4 mb-3\">クッキー（Cookies）の利用</h4>\n    <p>\n      当ウェブサイトでは、機能向上および利用状況の把握のためにクッキー（お客様のデバイスに保存される小さなデータファイル）を使用しています。これにより、再訪問者を識別し、より適切なコンテンツを提供することが可能になります。\n    </p>\n    <ul>\n      <li>クッキーは、お客様の同意なく個人情報を取得するものではありません</li>\n      <li>多くのブラウザは自動的にクッキーを受け入れますが、設定により無効にすることが可能です</li>\n      <li>クッキーを無効にした場合、ウェブサイトの一部機能が利用できなくなる可能性があります</li>\n    </ul>\n\n    <h4 class=\"mt-4 mb-3\">第三者ウェブサイトについて</h4>\n    <p class=\"mb-4\">\n      当ウェブサイトには、外部の第三者サイトへのリンクが含まれる場合があります。これらのサイトのプライバシーポリシーや運用について、当社は管理または責任を負いません。外部サイトをご利用の際は、各サイトのプライバシーポリシーをご確認いただくことをお勧めします。\n    </p>\n\n    <h4 class=\"mt-4 mb-3\">セキュリティ対策</h4>\n    <p class=\"mb-4\">\n      当社は、不正アクセス、改ざん、漏えい等からお客様の情報を保護するため、合理的な技術的および組織的安全対策を講じています。ただし、いかなるデジタルシステムも完全な安全性を保証するものではありません。当社の合理的な管理を超える事由による侵害、障害、または損失については責任を負いかねます。\n    </p>\n\n    <h4 class=\"mt-4 mb-3\">更新および変更</h4>\n    <p class=\"mb-3\">\n      当社は、本プライバシーポリシーを随時改定する権利を有します。変更内容は本ページに掲載されます。変更後も引き続き当ウェブサイトをご利用いただいた場合、改定内容に同意したものとみなされます。\n    </p>\n\n    <p class=\"mb-0\">\n      プライバシーに関するご質問やご要望がございましたら、サポートチームまでお問い合わせください。通常、2営業日以内にご回答いたします。\n    </p>\n\n  </div>\n</div>\n', NULL, NULL),
(3, 'Delivery Policy', '配送ポリシー', 'delivery-policy', '<div class=\"contact-content\">\r\n  <div class=\"page-cntnt\">\r\n    \r\n    <p class=\"mb-4\">\r\n      At LYPRO COMPANY LIMITED, all learning materials are delivered digitally to provide immediate and convenient access after purchase. This Delivery Policy explains how you will receive your course and what to expect following checkout.\r\n    </p>\r\n\r\n    <h4 class=\"mt-4 mb-3\">1. Digital Delivery Process</h4>\r\n\r\n    <h5 class=\"mt-3 mb-2\">Purchase Confirmation</h5>\r\n    <p>\r\n      Once your payment has been successfully processed, an automated confirmation email will be sent to the email address entered during checkout.\r\n    </p>\r\n    <p class=\"mb-3\">\r\n      This message contains your access credentials, course details, and instructions required to begin your training.\r\n    </p>\r\n\r\n    <h5 class=\"mt-3 mb-2\">Access Timeframe</h5>\r\n    <p>\r\n      In most cases, course access information is delivered within a few minutes.\r\n    </p>\r\n    <p>\r\n      Occasionally, delays caused by email service providers or high transaction volumes may extend delivery time up to 24 hours.\r\n    </p>\r\n    <p class=\"mb-4\">\r\n      We actively monitor our systems to maintain fast and reliable digital fulfillment.\r\n    </p>\r\n\r\n    <h4 class=\"mt-4 mb-3\">2. If You Do Not Receive Your Email</h4>\r\n    <ul>\r\n      <li><strong>Review Spam or Junk Folders:</strong> Automated notifications are sometimes misclassified</li>\r\n      <li><strong>Confirm Email Accuracy:</strong> Double-check that the email address entered at checkout was correct</li>\r\n      <li><strong>Reach Out to Support:</strong> If you still cannot locate the email, contact us at \r\n        <a href=\"mailto:contact@risebeyondgrowth.com\">contact@risebeyondgrowth.com</a> for prompt assistance\r\n      </li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-4 mb-3\">3. Important Conditions</h4>\r\n    <ul>\r\n      <li><strong>Electronic Distribution Only:</strong> All products are provided in digital format. No printed or physical materials will be mailed</li>\r\n      <li><strong>Personal Use License:</strong> Course materials are licensed for individual, non-commercial use. Reproduction, resale, redistribution, modification, or sharing without prior written authorization from LYPRO COMPANY LIMITED is strictly prohibited</li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-4 mb-3\">4. Assistance & Support</h4>\r\n    <p>\r\n      Our goal is to ensure uninterrupted access to your learning materials. If you experience delivery issues or have any related questions, please contact us:\r\n    </p>\r\n    <p>\r\n      <strong>Email:</strong> <a href=\"mailto:contact@risebeyondgrowth.com\">contact@risebeyondgrowth.com</a><br>\r\n      <strong>Estimated Response Time:</strong> Within 2 business days.\r\n    </p>\r\n\r\n  </div>\r\n</div>\r\n', '<div class=\"contact-content\">\r\n  <div class=\"page-cntnt\">\r\n    \r\n    <p class=\"mb-4\">\r\n      LYPRO COMPANY LIMITED では、すべての学習教材をデジタル形式で提供しており、ご購入後すぐに便利にご利用いただけます。本デリバリーポリシーでは、コースの受け取り方法およびご購入後の流れについてご説明します。\r\n    </p>\r\n\r\n    <h4 class=\"mt-4 mb-3\">1. デジタル配信の流れ</h4>\r\n\r\n    <h5 class=\"mt-3 mb-2\">購入確認</h5>\r\n    <p>\r\n      お支払い手続きが正常に完了すると、チェックアウト時に入力されたメールアドレス宛に自動確認メールが送信されます。\r\n    </p>\r\n    <p class=\"mb-3\">\r\n      このメールには、コースへのアクセス情報、詳細内容、および受講開始に必要な手順が記載されています。\r\n    </p>\r\n\r\n    <h5 class=\"mt-3 mb-2\">アクセスまでの時間</h5>\r\n    <p>\r\n      通常、コースのアクセス情報はご購入後数分以内に送信されます。\r\n    </p>\r\n    <p>\r\n      ただし、メールサーバーの遅延やアクセス集中などの理由により、最大で24時間程度かかる場合があります。\r\n    </p>\r\n    <p class=\"mb-4\">\r\n      当社では、迅速かつ確実なデジタル配信を維持するため、システムを継続的に監視しています。\r\n    </p>\r\n\r\n    <h4 class=\"mt-4 mb-3\">2. メールが届かない場合</h4>\r\n    <ul>\r\n      <li><strong>迷惑メールフォルダの確認：</strong> 自動送信メールが誤って振り分けられる場合があります</li>\r\n      <li><strong>メールアドレスの確認：</strong> ご購入時に入力したメールアドレスに誤りがないかご確認ください</li>\r\n      <li><strong>サポートへ連絡：</strong> メールが見つからない場合は、\r\n        <a href=\"mailto:contact@risebeyondgrowth.com\">contact@risebeyondgrowth.com</a> までご連絡ください。迅速に対応いたします\r\n      </li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-4 mb-3\">3. 重要事項</h4>\r\n    <ul>\r\n      <li><strong>デジタル配信のみ：</strong> すべての商品は電子形式で提供されます。印刷物や物理的な商品の発送は行っておりません</li>\r\n      <li><strong>個人利用ライセンス：</strong> コース教材は個人の非商用利用を目的として許諾されています。LYPRO COMPANY LIMITED の書面による事前承諾なしに、複製、再販売、再配布、改変、共有することは禁止されています</li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-4 mb-3\">4. サポートについて</h4>\r\n    <p>\r\n      当社は、お客様がスムーズに学習を開始できるよう努めています。配信に関する問題やご質問がある場合は、以下までお問い合わせください：\r\n    </p>\r\n    <p>\r\n      <strong>メール：</strong> <a href=\"mailto:contact@risebeyondgrowth.com\">contact@risebeyondgrowth.com</a><br>\r\n      <strong>通常の回答時間：</strong> 2営業日以内\r\n    </p>\r\n\r\n  </div>\r\n</div>\r\n', NULL, NULL),
(4, 'Terms & Conditions', 'ご利用規約', 'terms-conditions', '<!-- Company Details -->\r\n<div class=\"contact-content\">\r\n  <div class=\"content\">\r\n    <h4 class=\"title mb-2\">Registered Company</h4>\r\n    <p>LYPRO COMPANY LIMITED</p>\r\n  </div>\r\n\r\n  <div class=\"content\">\r\n    <h4 class=\"title mb-2\">Contact Email</h4>\r\n    <span>\r\n      <a href=\"mailto:contact@risebeyondgrowth.com\">contact@risebeyondgrowth.com</a>\r\n    </span>\r\n  </div>\r\n\r\n  <div class=\"content\">\r\n    <h4 class=\"title mb-2 mt-2\">Business Address</h4>\r\n    <p>Unit 308, 3/F., Chevalier House, 45-51 Chatham Road South, Tsim Sha Tsui, Hong Kong</p>\r\n  </div>\r\n</div>\r\n\r\n<!-- Terms & Conditions -->\r\n<div class=\"page-cntnt\">\r\n\r\n  <h4 class=\"mt-5 mb-3\">Overview</h4>\r\n  <p>\r\n    By accessing, purchasing, or using our digital courses, you acknowledge and agree to the following Terms and Conditions. If you do not agree with any part of these terms, you should discontinue use of our services.\r\n  </p>\r\n\r\n  <h4 class=\"mt-5 mb-3\">Scope of Services</h4>\r\n  <ul>\r\n    <li>We provide digital educational programs that become available after successful payment confirmation</li>\r\n    <li>Course access details are delivered to the email address supplied during checkout</li>\r\n    <li>Access to purchased content remains active for fourteen (14) days from the date of delivery</li>\r\n    <li>We may revise, suspend, modify, or terminate any service offering with prior notice. Any refund decisions are made in accordance with our internal policies and at our discretion</li>\r\n  </ul>\r\n\r\n  <h4 class=\"mt-5 mb-3\">Billing & Payment Terms</h4>\r\n  <ul>\r\n    <li>Transactions are processed securely through authorized payment service providers</li>\r\n    <li>Accepted currencies include Japanese Yen (JP¥), United States Dollars (US$), and Hong Kong Dollars (HK$)</li>\r\n    <li>After payment confirmation, a transaction reference number (Order ID) will be emailed for your records</li>\r\n  </ul>\r\n\r\n  <h4 class=\"mt-5 mb-3\">Refunds & Cancellations</h4>\r\n  <ul>\r\n    <li>Requests for refunds must be submitted within fourteen (14) days of the purchase date and are assessed under our official Refund Policy</li>\r\n    <li>Cancellation requests are evaluated individually and are subject to the applicable Cancellation Policy terms</li>\r\n  </ul>\r\n\r\n  <h4 class=\"mt-5 mb-3\">Ownership & Intellectual Rights</h4>\r\n  <ul>\r\n    <li>All educational materials, including text, media, and resources, are protected by applicable intellectual property laws</li>\r\n    <li>Content is licensed for personal, non-commercial use only. Copying, distributing, reselling, altering, or publicly sharing materials without prior written authorization is strictly prohibited</li>\r\n  </ul>\r\n\r\n  <h4 class=\"mt-5 mb-3\">Disclaimer of Warranties & Limitation of Liability</h4>\r\n  <ul>\r\n    <li>All courses are provided on an “as available” basis without guarantees of uninterrupted availability or error-free performance</li>\r\n    <li>We shall not be liable for indirect, incidental, or consequential damages resulting from the use of our courses or services</li>\r\n  </ul>\r\n\r\n  <h4 class=\"mt-5 mb-3\">Data Privacy</h4>\r\n  <ul>\r\n    <li>By providing your information, you consent to its use for order processing, course delivery, and customer support</li>\r\n    <li>Personal data will not be disclosed to third parties except where required by applicable law</li>\r\n  </ul>\r\n\r\n  <h4 class=\"mt-5 mb-3\">Confidential Information</h4>\r\n  <p class=\"mb-4\">\r\n    Any sensitive or confidential information exchanged within the course environment will be handled responsibly and will not be disclosed to external parties without your explicit permission, unless legally required.\r\n  </p>\r\n\r\n  <h4 class=\"mt-5 mb-3\">Applicable Law & Legal Venue</h4>\r\n  <p>\r\n    These Terms and Conditions are governed by the laws of the United Kingdom.<br>\r\n    Charges made through this website will appear on your credit card statement as\r\n    <img src=\"assets/images/dba2.png\" class=\"dba-img1\" alt=\"KnowledgeCademy\"><br>\r\n    Any disputes arising from the use of our services shall be subject to the exclusive jurisdiction of the courts of the United Kingdom.\r\n  </p>\r\n\r\n</div>\r\n', '\r\n  <!-- Company Info -->\r\n  <div class=\"contact-content\">\r\n    <div class=\"content\">\r\n      <h4 class=\"title mb-2\">会社名</h4>\r\n      <p>LYPRO COMPANY LIMITED</p>\r\n    </div>\r\n\r\n    <div class=\"content\">\r\n      <h4 class=\"title mb-2\">メールアドレス</h4>\r\n      <span>\r\n        <a href=\"mailto:contact@risebeyondgrowth.com\">contact@risebeyondgrowth.com</a>\r\n      </span>\r\n    </div>\r\n\r\n    <div class=\"content\">\r\n      <h4 class=\"title mb-2 mt-2\">所在地</h4>\r\n      <p>Unit 308, 3/F., Chevalier House, 45-51 Chatham Road South, Tsim Sha Tsui, Hong Kong</p>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Terms & Conditions Content -->\r\n  <div class=\"page-cntnt\">\r\n\r\n    <h4 class=\"mt-5 mb-3\">はじめに</h4>\r\n    <p>\r\n      当社のコースをお選びいただきありがとうございます。本デジタル学習コンテンツにアクセスし購入することにより、以下に記載された条件に同意したものとみなされます。これらの条件に同意いただけない場合は、当社サービスのご利用をお控えください。\r\n    </p>\r\n\r\n    <h4 class=\"mt-5 mb-3\">提供サービス</h4>\r\n    <ul >\r\n      <li>当社は、購入完了後に利用可能となるデジタル教育コンテンツを提供します</li>\r\n      <li>コース教材は、決済時にご入力いただいたメールアドレスへ送信されます</li>\r\n      <li>コースコンテンツの利用期間は、配信日から2週間です</li>\r\n      <li>\r\n        当社は、事前通知のうえでサービス内容の更新、変更、一時停止、または終了を行う権利を有します。返金が発生する場合は、当社の裁量により対応されます\r\n      </li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-5 mb-3\">お支払いおよび取引</h4>\r\n    <ul >\r\n      <li>すべてのお支払いは、信頼できる決済ゲートウェイを通じて安全に処理されます</li>\r\n      <li>受け入れられる通貨には、日本円（JP¥）、米ドル（US$）、香港ドル（HK$）が含まれます</li>\r\n      <li>決済完了後、確認用として注文IDがご登録のメールアドレスへ送信されます</li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-5 mb-3\">返金およびキャンセルポリシー</h4>\r\n    <ul >\r\n      <li>返金の申請は購入日から14日以内に行う必要があり、当社の返金ポリシーに基づき審査されます</li>\r\n      <li>キャンセルの申請は個別に審査され、当社のキャンセルポリシーの条件が適用されます</li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-5 mb-3\">知的財産権</h4>\r\n    <ul >\r\n      <li>すべてのコース教材は知的財産法により保護されており、個人利用のみを目的としています</li>\r\n      <li>コンテンツの再配布、再販売、複製、改変は固く禁止されています</li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-5 mb-3\">責任制限および免責事項</h4>\r\n    <ul >\r\n      <li>すべてのコースは「現状有姿」で提供され、継続的なアクセスや技術的問題が発生しないことを保証するものではありません</li>\r\n      <li>コースの利用に起因する間接的または結果的損害について、当社は一切の責任を負いません</li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-5 mb-3\">プライバシーおよびデータ保護</h4>\r\n    <ul >\r\n      <li>情報をご提供いただくことで、コース配信およびサポート目的でのデータ利用に同意したものとみなされます</li>\r\n      <li>法令により要求される場合を除き、個人情報を第三者と共有することはありません</li>\r\n    </ul>\r\n\r\n    <h4 class=\"mt-5 mb-3\">機密情報</h4>\r\n    <p class=\"mb-4\">\r\n      コース環境内で共有される機密情報は厳重に保護され、お客様の明示的な同意なしに第三者へ開示されることはありません。\r\n    </p>\r\n\r\n    <h4 class=\"mt-5 mb-3\">準拠法および管轄</h4>\r\n    <p>\r\n     これらの利用規約は、英国の法律に準拠します。<br>\r\n      このウェブサイトを通じて行われた料金は、クレジットカードの明細書に次のように表示されます\r\n      <img src=\"assets/images/dba2.png\" class=\"dba-img1\" alt=\"KnowledgeCademy\" style=\"\"><br>\r\n      当社のサービスの使用に起因する紛争は、英国の裁判所の専属管轄権に従うものとします。\r\n    </p>\r\n\r\n  </div>\r\n\r\n\r\n', NULL, NULL);
INSERT INTO `pages` (`id`, `page_title`, `page_title_ja`, `page_slug`, `page_desc`, `page_desc_ja`, `page_meta`, `page_keywords`) VALUES
(5, 'About Us', '私達について', 'about-us', '\n\n      <!-- student-choose-area start -->\n      <div class=\"student-choose-area fix pt-110 pb-90\">\n         <div class=\"container\">\n            <div class=\"row\">\n               <div class=\"col-xl-5 col-lg-5\">\n                  <div class=\"student-wrapper mb-30\">\n                     <div class=\"section-title mb-30\">\n                        <h2>Why Learners <span class=\"down-mark-line\">Choose</span> Us to Build Skills That Make a Difference</h2>\n                     </div>\n                     <div class=\"sitdent-choose-content\">\n                        <p>Building skills and accelerating careers shouldn’t be an afterthought.\n                            In today’s competitive world, learners are looking for meaningful, flexible, and result-driven education—and that’s exactly what we deliver. With expert-designed content and learner-first tools, we’re helping thousands upgrade their future.\n                        </p>\n                     </div>\n                     <div class=\"student-choose-list\">\n                        <ul>\n                           <li><i class=\"far fa-check\"></i>Interactive Learning Experience</li>\n                           <p>Courses designed with real-life case studies, tools, and exercises for better understanding.</p>\n                           <li><i class=\"far fa-check\"></i>Simple & Seamless Enrollment</li>\n                           <p>Just a few clicks to get started. No complicated forms or waiting time.</p>\n                           <li><i class=\"far fa-check\"></i>Expert Instructors from Industry</li>\n                           <p>Our instructors are professionals with years of field experience—bringing real knowledge, not just theory.</p>\n                           <li><i class=\"far fa-check\"></i>Flexible Access</li>\n                           <p>Learn anytime, anywhere, on any device—your progress syncs automatically.</p>\n                        </ul>\n                     </div>\n                  </div>\n               </div>\n               <div class=\"col-xl-2 col-lg-2\">\n                  <div class=\"student-wrapper position-relative\">\n                     <div class=\"shap-01\">\n                     </div>\n                  </div>\n               </div>\n               <div class=\"col-xl-5 col-lg-5\">\n                  <div class=\"student-choose-wrapper position-relative mb-30\">\n                     <div class=\"shap-02\">\n                     </div>\n                     <div class=\"shap-03\">\n                        <img src=\"/assets/img/shape/student-shape-03.png\" alt=\"image not found\">\n                     </div>\n                     <div class=\"shap-04\">\n                        <img src=\"/assets/img/shape/student-shape-04.png\" alt=\"image not found\">\n                     </div>\n                     <div class=\"shap-05\">\n                        <img src=\"/assets/img/shape/student-shape-05.png\" alt=\"image not found\">\n                     </div>\n                     <div class=\"shap-06\">\n                        <img src=\"/assets/img/shape/student-shape-06.png\" alt=\"image not found\">\n                     </div>\n                     <div class=\"shap-07\">\n                        <img src=\"/assets/img/shape/student-shape-07.png\" alt=\"image not found\">\n                     </div>\n\n                     <div class=\"student-choose-thumb\">\n                        <img src=\"/assets/img/student-choose/student.png\" alt=\"image not found\">\n                     </div>\n                  </div>\n               </div>\n            </div>\n         </div>\n      </div>\n      <!-- student-choose-area end -->\n      <section class=\"section-story padding-tb-50\">\n         <div class=\"container\">\n           <div class=\"row\">\n             <div class=\"col-12\">\n               <div class=\"section-title bb-center\" data-aos=\"fade-up\" data-aos-duration=\"1000\" data-aos-delay=\"200\">\n                 <div class=\"section-detail\">\n                   <h2 class=\"bb-title\" style=\"text-align: center;\">How It All <span>Started</span></h2>\n                 </div>\n               </div>\n             </div>\n       \n             <div class=\"col-lg-10 offset-lg-1\">\n               <div class=\"story-detail\" data-aos=\"fade-up\" data-aos-duration=\"1000\" data-aos-delay=\"400\">\n                 \n                 <div class=\"block\">\n                   <h3>A Simple Idea</h3>\n                   <p>It began with a simple idea — what if learning could be more flexible, more accessible, and truly inspiring? A small group of educators, tech enthusiasts, and dreamers came together, all fueled by the same passion: to make quality education available to anyone, anywhere.</p>\n                 </div>\n       \n                 <div class=\"block\">\n                   <h3>A Passion Turned into Purpose</h3>\n                   <p>Frustrated by outdated systems and limited access, we saw an opportunity to do things differently. We weren’t just building a platform — we were creating a learning experience designed around real people, real goals, and real growth.</p>\n                 </div>\n       \n                 <div class=\"block\">\n                   <h3>Building Something Meaningful</h3>\n                   <p>Armed with industry experience and a desire to innovate, we set out to design practical, engaging courses across fields like business, tech, design, and personal development. Every course is built with purpose — by experts, for learners.</p>\n                 </div>\n       \n                 <div class=\"block\">\n                   <h3>Why We Do It</h3>\n                   <p>Our mission has always been simple: to empower individuals with the tools and confidence to grow. Whether it’s picking up a new skill, exploring a passion, or making a career move — we’re here to support every step of the journey.</p>\n                 </div>\n       \n                 <div class=\"block\">\n                   <h3>The Road Ahead</h3>\n                   <p>This is just the beginning. As we continue to grow, so does our commitment to delivering meaningful education that adapts to your needs. The future of learning is personal, and we’re excited to be part of yours.</p>\n                 </div>\n                 \n               </div>\n             </div>\n           </div>\n         </div>\n       </section>\n       \n      <!-- features-area-start -->\n      <div class=\"features-area section-bg fix pt-110\">\n         <div class=\"container\">\n            <div class=\"row\">\n               <div class=\"col-12\">\n                  <div class=\"section-title text-center mb-60\">\n                     <h2>Accelerate Your Growth <br>\n                        with <span class=\"down-mark-line-2\">Cloud-Bizinfo.com</span></h2>\n                  </div>\n               </div>\n               <div class=\"col-xl-4 col-lg-4 col-md-6 col-sm-12\">\n                  <div class=\"features-box text-center mb-30\">\n                     <div class=\"features-svg\">\n                        <svg id=\"Group_3029\" data-name=\"Group 3029\" xmlns=\"http://www.w3.org/2000/svg\" width=\"79.896\"\n                           height=\"78.92\" viewBox=\"0 0 79.896 78.92\">\n                           <path id=\"Path_7772\" data-name=\"Path 7772\"\n                              d=\"M82.875,23.294a1.417,1.417,0,0,1-1.417-1.417v-4.6a1.417,1.417,0,0,1,2.833,0v4.6A1.417,1.417,0,0,1,82.875,23.294Z\"\n                              transform=\"translate(-29.154 -9.968)\" fill=\"#3b4456\" />\n                           <path id=\"Path_7773\" data-name=\"Path 7773\"\n                              d=\"M51.863,65.151a1.417,1.417,0,0,1-1.315-.888c-1.314-3.258-5.242-4.975-5.279-4.992a1.417,1.417,0,1,1,1.109-2.607c.2.087,5.038,2.179,6.8,6.539a1.417,1.417,0,0,1-.783,1.842,1.4,1.4,0,0,1-.529.106Z\"