INSERT INTO `products` (`id`, `title`, `title_jp`, `slug`, `summary`, `summary_jp`, `description`, `description_jp`, `meta_title`, `meta_description`, `meta_keyword`, `photo`, `stock`, `size`, `condition`, `status`, `price`, `price_jp`, `price_hk`, `discount`, `is_featured`, `extra_description`, `extra_description_jp`, `cat_id`, `child_cat_id`, `brand_id`, `duration`, `skill_level`, `skill_level_jp`, `lectures`, `language`, `language_jp`, `created_at`, `updated_at`) VALUES
(1, 'Programming Fundamentals', 'プログラミングの基礎', 'programming-fundamentals', 'Covers programming concepts from basic logic and syntax to advanced software design principles. Learners progress from understanding how code works to writing structured, efficient, and scalable programs used in professional and enterprise development environments.', '基本的なロジックと構文から高度なソフトウェア設計の原則まで、プログラミングの概念をカバーしています。 学習者は、コードがどのように機能するかを理解することから、専門的および企業の開発環境で使用される構造化された効率的でスケーラブルなプ', 'Programming Fundamentals introduces learners to the core concepts of software development, starting with basic programming logic and gradually building toward professional coding practices. Beginners learn how programs work and how to think logically, intermediary learners gain confidence using common programming structures, advanced learners focus on writing clean and maintainable code, and expert learners develop an understanding of software architecture and performance considerations.', 'プログラミングの基礎は、基本的なプログラミングロジックから始まり、徐々にプロのコーディング実践に向けて構築し、ソフトウェ 初心者はプログラムがどのように動作し、論理的に考えるかを学び、中間学習者は一般的なプログラミング構造を使用して自信を得、上級学習者はクリーンで保守可能なコードを書くことに焦点を当て、専門家学習者はソフトウェアアーキテクチャとパフォーマンスの考慮事項について理解を深めます。', 'Programming Fundamentals', 'Learn the core concepts of programming, including logic, variables, and problem solving, designed for beginners starting their coding journey.', 'programming basics, coding fundamentals, beginner programming, software basics, learn programming', 'storage/photos/products/1.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 1, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(2, 'Web Application Development', 'Webアプリケーション開発', 'web-application-development', 'Explains web application development from foundational web concepts through full-stack implementation and deployment. Learners advance from simple page structures to building secure, scalable, and high-performance web applications using modern development practices.', '基本的なweb概念からフルスタックの実装と展開まで、webアプリケーション開発について説明します。 学習者は、単純なページ構造から、最新の開発プラクティスを使用して、安全でスケーラブルで高性能なwebアプリケーションを構築することに進みます。', 'Web Application Development guides learners through the complete process of building modern web applications. Beginners start by understanding how the web works, intermediary learners develop simple frontend and backend components, advanced learners build full-stack applications with APIs and deployment workflows, and expert learners focus on designing secure, scalable, and high-performance web architectures.', 'Webアプリケーション開発は、最新のwebアプリケーションを構築する完全なプロセスを学習者に案内します。 初心者は、webの仕組みを理解することから始め、中間学習者はシンプルなフロントエンドとバックエンドコンポーネントを開発し、上級学習者はApiとデプロイワークフローを備えたフルスタックアプリケーションを構築し、専門家学習者は安全でスケーラブルで高性能なwebアーキテクチャの設計に焦点を当てます。', 'Web Application Development', 'Build modern web applications by learning front-end and back-end development concepts used in real-world projects.', 'web development, web application development, frontend backend, build web apps, web programming', 'storage/photos/products/2.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 1, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(3, 'Software Testing & Code Quality', 'ソフトウェアテストとコード品質', 'software-testing-code-quality', 'Introduces software testing from basic quality concepts to advanced automation and enterprise testing strategies. Learners progress from understanding defects to implementing structured testing frameworks that ensure reliability, maintainability, and long-term software quality.', '基本的な品質概念から高度な自動化および企業テスト戦略まで、ソフトウェアテストを紹介します。 学習者は、欠陥の理解から、信頼性、保守性、および長期的なソフトウェア品質を保証する構造化されたテストフレームワークの実装に進みます。', 'Software Testing & Code Quality focuses on building reliable and maintainable software through structured testing practices. Beginners learn why testing is important, intermediary learners create test cases and perform basic testing, advanced learners implement automated testing within development workflows, and expert learners design enterprise-level testing strategies and continuous integration quality systems.', 'ソフトウェアテストとコード品質は、構造化されたテスト慣行を通じて、信頼性が高く保守可能なソフトウェアを構築することに焦点を当てています。 初心者はテストが重要である理由を学び、中間学習者はテストケースを作成して基本的なテストを実行し、上級学習者は開発ワークフロー内で自動テストを実装し、専門家学習者はエンタープライズレベルのテスト戦略と継続的な統合品質システムを設計します。', 'Software Testing & Code Quality', 'Understand software testing methods and best practices to improve code quality, reliability, and performance.', 'software testing, code quality, QA testing, testing fundamentals, quality assurance', 'storage/photos/products/3.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 1, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(4, 'Data Analysis Fundamentals', 'データ分析の基礎', 'data-analysis-fundamentals', 'Covers data analysis from basic data handling to advanced analytical interpretation. Learners progress from understanding datasets and simple analysis to applying insights strategically for business decision-making and organizational performance improvement.', '基本的なデータ処理から高度な分析解釈までのデータ分析をカバーしています。 学習者は、データセットの理解と簡単な分析から、ビジネス上の意思決定と組織のパフォーマンス向上のために戦略的に洞察を適用することに進', 'Data Analysis Fundamentals teaches learners how to work with data to support effective decision-making. Beginners start with understanding data types and basic organization, intermediary learners perform simple analysis and reporting, advanced learners identify trends and visualize insights, and expert learners apply data analysis strategically to organizational planning and performance improvement.', 'データ分析の基礎は、効果的な意思決定を支援するためにデータを使用する方法を学習者に教えます。 初心者はデータ型と基本的な組織を理解することから始まり、中間学習者は簡単な分析とレポートを実行し、上級学習者は傾向を特定して洞察を視覚化し、専門家学習者は組織の計画とパフォーマンスの改善に戦略的にデータ分析を適用します。', 'Data Analysis Fundamentals', 'Learn how to collect, analyze, and interpret data to support better decisions using practical data analysis techniques.', 'data analysis basics, data fundamentals, data interpretation, analytics foundations, data skills', 'storage/photos/products/4.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 2, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(5, 'Business Automation & Scripting', 'ビジネス自動化とスクリプト', 'business-automation-scripting', 'Introduces automation concepts from basic task simplification to advanced scripting and workflow optimization. Learners progress from identifying automation opportunities to designing scalable automation solutions that improve efficiency across business operations.', '基本的なタスクの簡素化から高度なスクリプトとワークフローの最適化まで、自動化の概念を紹介します。 学習者は、自動化の機会を特定することから、ビジネスオペレーション全体の効率を向上させるスケーラブルな自動化ソリューションの設計に進みます。', 'Business Automation & Scripting helps learners improve efficiency by reducing repetitive tasks through automation. Beginners understand automation concepts, intermediary learners create simple scripts, advanced learners design integrated workflows across systems, and expert learners build scalable automation strategies and governance models for enterprise environments.', 'ビジネスオートメーションとスクリプトは、学習者が自動化によって反復的なタスクを減らすことによって効率を向上させるのに役立ちます。 初心者は自動化の概念を理解し、中間学習者は簡単なスクリプトを作成し、上級学習者はシステム間で統合されたワークフローを設計し、専門家学習者はエンタープライズ環境向けのスケーラブルな自動化戦略とガバナンスモデルを構築します。', 'Business Automation & Scripting', 'Learn how to automate repetitive business tasks using scripts to save time and improve efficiency.', 'business automation, scripting basics, workflow automation, automation scripts, productivity tools', 'storage/photos/products/5.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 2, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(6, 'AI Tools & Practical Applications', 'AIツール＆実用化', 'ai-tools-practical-applications', 'Explains AI usage from basic tool understanding to advanced practical implementation. Learners progress from everyday AI applications to integrating intelligent tools strategically within workflows while considering responsible and effective organizational adoption.', '基本的なツールの理解から高度な実用化まで、AIの使い方を説明します。 学習者は、責任ある効果的な組織の採用を検討しながら、日常のAIアプリケーションからワークフロー内で戦略的にインテリジェントなツールを統合することに進みます。', 'AI Tools & Practical Applications introduces learners to applying artificial intelligence in real-world workflows. Beginners explore basic AI tools, intermediary learners apply AI to productivity and analysis tasks, advanced learners integrate AI into business processes, and expert learners focus on responsible organizational AI adoption and long-term value creation.', 'AIツールと実用的なアプリケーション学習者は、現実世界のワークフローで人工知能を適用することを紹介します。 初心者は基本的なAIツールを探索し、中間学習者は生産性と分析タスクにAIを適用し、上級学習者はAIをビジネスプロセスに統合し、専門家学習者は責任ある組織のAIの採用と長期的な価値創造に焦点を当てます。', 'AI Tools & Practical Applications', 'Explore practical AI tools and learn how to apply them to real-world tasks across business and technology.', 'AI tools, artificial intelligence applications, practical AI, AI for business, automation AI', 'storage/photos/products/6.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 2, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(7, 'IT Infrastructure Fundamentals', 'ITインフラの基礎', 'it-infrastructure-fundamentals', 'Covers IT infrastructure from fundamental system components to advanced infrastructure design. Learners progress from understanding servers and networks to managing, optimizing, and planning reliable enterprise-grade IT environments.', '基本的なシステムコンポーネントから高度なインフラ設計まで、ITインフラストラクチャをカバーしています。 学習者は、サーバーとネットワークの理解から、信頼性の高いエンタープライズグレードのIT環境の管理、最適化、計画に進みます。', 'IT Infrastructure Fundamentals provides an understanding of the systems supporting modern IT environments. Beginners learn about servers and networks, intermediary learners manage system operations, advanced learners optimize infrastructure performance and reliability, and expert learners design and plan enterprise-grade IT infrastructure.', 'ITインフラストラクチャの基礎は、現代のIT環境をサポートするシステムの理解を提供します。 初心者はサーバーとネットワークについて学び、中間学習者はシステム運用を管理し、上級学習者はインフラストラクチャのパフォーマンスと信頼性を最適化し、専門家学習者はエンタープライズグレードのITインフラストラクチャを設計および計画します。', 'IT Infrastructure Fundamentals', 'Learn the basics of IT infrastructure, including networks, servers, and systems that support modern technology.', 'IT infrastructure, networking basics, servers fundamentals, IT systems, infrastructure basics', 'storage/photos/products/7.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 3, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(8, 'Cloud Computing Essentials', 'クラウドコンピューティングの必需品', 'cloud-computing-essentials', 'Introduces cloud computing from basic service concepts to advanced cloud architecture and governance. Learners progress from deploying simple resources to managing scalable, cost-efficient, and secure multi-cloud environments.', '基本的なサービス概念から高度なクラウドアーキテクチャとガバナンスまでのクラウドコンピューティングを紹介します。 学習者は、シンプルなリソースの展開から、スケーラブルでコスト効率が高く、安全なマルチクラウド環境の管理に進みます。', 'Cloud Computing Essentials introduces learners to cloud platforms and modern infrastructure models. Beginners understand cloud concepts, intermediary learners deploy and manage cloud resources, advanced learners design scalable and secure architectures, and expert learners manage multi-cloud strategies, cost optimization, and enterprise governance.', 'Cloud Computing Essentialsでは、学習者にクラウドプラットフォームと最新のインフラストラクチャモデルを紹介します。 初心者はクラウドの概念を理解し、中間学習者はクラウドリソースを展開および管理し、上級学習者はスケーラブルで安全なアーキテクチャを設計し、専門家学習者はマルチクラウド戦略、コスト最適化、エンタープライズガバナンスを管理します。', 'Cloud Computing Essentials', 'Understand core cloud computing concepts, services, and benefits used by modern organizations.', 'cloud computing basics, cloud essentials, cloud services, cloud fundamentals, IT cloud', 'storage/photos/products/8.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 3, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(9, 'DevOps & CI/CD Foundations', 'DevOps&CI/CD基盤', 'devops-cicd-foundations', 'Explains DevOps practices from foundational concepts to advanced CI/CD automation. Learners progress from understanding development workflows to implementing scalable pipelines that improve reliability, speed, and collaboration across engineering teams.', '基礎的な概念から高度なCI/CD自動化まで、DevOpsの実践について説明します。 学習者は、開発ワークフローの理解から、エンジニアリングチーム間の信頼性、スピード、コラボレーションを向上させるスケーラブルなパイプラインの実装まで、進歩しています。', 'DevOps & CI/CD Foundations explains how modern development and operations practices improve software delivery. Beginners learn DevOps concepts, intermediary learners build CI/CD pipelines, advanced learners implement automation and infrastructure as code, and expert learners scale DevOps practices across organizations and align them with business goals.', 'DevOps&CI/CD Foundationsでは、最新の開発および運用プラクティスがソフトウェア配信をどのように改善するかについて説明しています。 初心者はDevOpsの概念を学び、中間学習者はCI/CDパイプラインを構築し、上級学習者は自動化とインフラストラクチャをコードとして実装し、専門家学習者は組織全体でDevOpsプラクティスを拡張し、ビジネス目標に合わせます。', 'DevOps & CI/CD Foundations', 'Learn DevOps principles and CI/CD practices that help teams build, test, and deploy software faster.', 'DevOps basics, CI CD fundamentals, software deployment, automation pipelines, DevOps practices', 'storage/photos/products/9.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 3, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(10, 'Cybersecurity & Risk Management', 'サイバーセキュリティとリスク管理', 'cybersecurity-risk-management', 'Covers cybersecurity from basic threat awareness to advanced risk management strategies. Learners progress from understanding common vulnerabilities to implementing security controls, incident response processes, and enterprise-level security governance.', '基本的な脅威認識から高度なリスク管理戦略まで、サイバーセキュリティをカバーしています。 学習者は、一般的な脆弱性の理解から、セキュリティ制御、インシデント対応プロセス、企業レベルのセキュリティガバナンスの実装に進みます。', 'Cybersecurity & Risk Management prepares learners to protect systems and data from security threats. Beginners gain awareness of common risks, intermediary learners apply security controls, advanced learners manage incident response and operational security, and expert learners oversee enterprise security governance, risk assessment, and long-term security strategy.', 'サイバーセキュリティとリスク管理は、セキュリティの脅威からシステムとデータを保護するために学習者を準備します。 初心者は一般的なリスクの認識を獲得し、中間学習者はセキュリティ制御を適用し、上級学習者はインシデント対応と運用セキュリティを管理し、専門家学習者はエンタープライズセキュリティガバナンス、リスク評価、および長期的なセキュリティ戦略を監督します。', 'Cybersecurity & Risk Management', 'Learn cybersecurity fundamentals and risk management practices to help protect systems and data.', 'cybersecurity basics, risk management, information security, cyber threats, security fundamentals', 'storage/photos/products/10.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 3, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(11, 'UX Design Foundations & User Research', 'UXデザイン基盤とユーザー研究', 'ux-design-foundations-user-research', 'This course builds a strong foundation in user experience design and research methodology. Learners explore user-centered principles, persona development, journey mapping, and usability testing frameworks. The focus is on translating user insights into structured design decisions that improve product clarity and usability.', 'このコースは、ユーザーエクスペリエンスの設計と研究方法論の強力な基盤を構築します。 学習者は、ユーザー中心の原則、ペルソナ開発、ジャーニーマッピング、およびユーザビリティテストフレームワークを探ります。 焦点は、製品の明快さと使いやすさを向上させる構造化された設計上の意思決定にユーザーの洞察を翻訳することにあります。', 'UX Design Foundations & User Research provides a comprehensive pathway into user-centered design, starting with core principles of usability, accessibility, and human behavior in digital environments. At the foundational level, learners explore research planning, qualitative and quantitative methods, persona creation, and journey mapping. As the course progresses into intermediate concepts, participants learn how to synthesize research findings into actionable design insights, define problem statements, and prioritize user needs within product constraints. At the advanced stage, learners conduct structured usability testing, analyze behavioral data, and translate insights into measurable design improvements. By the end of the program, participants are equipped to approach digital product design with evidence-based reasoning and strategic clarity.', 'UXデザインの基礎とユーザー研究は、デジタル環境におけるユーザビリティ、アクセシビリティ、人間の行動の中核原則から始まり、ユーザー中心のデザインへの包括的な経路を提供します。 基礎レベルでは、学習者は研究計画、定性的および定量的方法、ペルソナ作成、およびジャーニーマッピングを探求します。 コースが中間概念に進むにつれて、参加者は、研究結果を実用的な設計洞察に統合し、問題文を定義し、製品の制約内でユーザーのニーズに優先順位を付ける方法を学びます。 高度な段階では、学習者は構造化されたユーザビリティテストを実施し、行動データを分析し、洞察を測定可能な設計改善に変換します。 プログラムの終わりまでに、参加者は証拠に基づいた推論と戦略的な明快さでデジタル製品設計にアプローチするために装備されています。', 'UX Design Foundations & User Research Course', 'Learn UX design principles, user research methods, personas, and usability testing to create intuitive and user-centered digital products.', 'ux design course, user research training, usability testing, user experience foundations, product design course', 'storage/photos/products/11.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 4, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(12, 'UI Design Systems & Prototyping', 'UIデザインシステム＆プロトタイピング', 'ui-design-systems-prototyping', 'This course teaches scalable interface design through structured design systems and interactive prototyping. Learners develop skills in visual hierarchy, component consistency, and modern UI frameworks. The program emphasizes building maintainable and high-performing digital interfaces across platforms.', 'このコースでは、構造化された設計システムと対話型プロトタイピングを通じて、スケーラブルなインターフェイス設計を教えます。 学習者は、視覚的な階層、コンポーネントの一貫性、および最新のUIフレームワークのスキルを開発します。 このプログラムは、プラットフォーム間で保守可能で高性能なデジタルインターフェイスを構築することを強調しています。', 'UI Design Systems & Prototyping guides learners through the structured creation of scalable, consistent, and visually refined interfaces. The beginner level introduces layout principles, typography systems, spacing logic, and the fundamentals of visual hierarchy. Moving into intermediate topics, learners construct reusable components, define design tokens, and develop cohesive style guides that ensure cross-platform consistency. At the advanced level, the focus shifts to interactive prototyping, motion principles, responsive behaviors, and collaboration workflows between design and development teams. The course emphasizes efficiency, maintainability, and modern interface architecture, enabling participants to design digital products that scale seamlessly across growing ecosystems.', 'UIデザインシステムとプロトタイピングは、スケーラブルで一貫性のある視覚的に洗練されたインターフェースの構造化された作成を通じて学習者をガイドします。 初心者レベルでは、レイアウトの原則、タイポグラフィシステム、間隔ロジック、および視覚的階層の基礎を紹介します。 中間的なトピックに移動すると、学習者は再利用可能なコンポーネントを構築し、デザイントークンを定義し、クロスプラットフォームの一貫性を確保するまとまりのあるスタイルガイドを開発します。 高度なレベルでは、インタラクティブプロトタイピング、モーション原理、レスポンシブビヘイビア、および設計チームと開発チーム間のコラボレーションワークフローに焦点がシフトします。 このコースでは、効率性、保守性、最新のインターフェイスアーキテクチャを重視し、参加者は成長するエコシステム全体でシームレスに拡張できるデジタル製品を設計することができます。', 'UI Design Systems & Prototyping Training', 'Master UI design systems, visual hierarchy, and interactive prototyping to build scalable and modern digital interfaces.', 'ui design course, design systems training, prototyping course, interface design, digital product design', 'storage/photos/products/12.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 4, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(13, 'Product Thinking & Digital Strategy', '製品思考とデジタル戦略', 'product-thinking-digital-strategy', 'This course develops strategic product thinking aligned with user needs and business objectives. Learners explore digital strategy frameworks, roadmap planning, and product lifecycle management. The focus is on building value-driven products that support long-term growth and market relevance.', 'このコースでは、ユーザーのニーズやビジネス目標に沿った戦略的な製品思考を開発します。 学習者は、デジタル戦略のフレームワーク、ロードマップ計画、製品ライフサイクル管理について説明します。 焦点は、長期的な成長と市場の関連性をサポートする価値主導型製品の構築にあります。', 'Product Thinking & Digital Strategy develops a structured mindset for building digital products that align customer value with long-term business direction. At the introductory stage, learners examine product discovery frameworks, customer problem validation, and value proposition design. As they advance, the course explores competitive positioning, roadmap planning, growth experimentation, and prioritization models that balance impact and feasibility. In the advanced phase, participants work through strategic alignment techniques, product-market fit evaluation, and data-informed decision frameworks that guide sustainable scaling. The program equips learners with the analytical tools and strategic discipline required to lead product initiatives in dynamic digital markets.', '製品思考とデジタル戦略顧客価値と長期的なビジネスの方向性を一致させるデジタル製品を構築するための構造化された考え方を開発します。 入門段階では、学習者は製品発見フレームワーク、顧客の問題検証、および価値提案の設計を検討します。 彼らが進むにつれて、コースでは、競争力のあるポジショニング、ロードマップ計画、成長の実験、および影響と実現可能性のバランスをとる優先順位付けモデルを探ります。 高度な段階では、参加者は戦略的なアライメント技術、製品市場適合評価、および持続可能なスケーリングを導くデータ情報に基づいた意思決定フレームワークを介して作業します。 このプログラムでは、動的なデジタル市場で製品イニシアチブをリードするために必要な分析ツールと戦略的規律を学習者に提供します。', 'Product Thinking & Digital Strategy Course', 'Develop product thinking skills and digital strategy frameworks to align user needs with business objectives and product growth.', 'product thinking course, digital strategy training, product roadmap planning, tech product management, digital experience strategy', 'storage/photos/products/13.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 4, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(14, 'Interaction Design & Experience Optimization', 'インタラクションデザインと体験の最適化', 'interaction-design-experience-optimization', 'This course focuses on designing meaningful interactions that enhance usability and engagement. Learners study behavioral patterns, micro-interactions, and performance optimization techniques. The goal is to improve digital experiences through measurable usability and engagement improvements.', 'このコースでは、ユーザビリティとエンゲージメントを向上させる意味のあるインタラクションの設計に焦点を当てています。 学習者は、行動パターン、マイクロインタラクション、およびパフォーマンス最適化技術を研究します。 目標は、測定可能なユーザビリティとエンゲージメントの改善を通じてデジタルエクスペリエンスを向上させることです。', 'Interaction Design & Experience Optimization focuses on crafting intuitive and meaningful user interactions that enhance digital engagement. At the foundational level, learners explore interaction principles, feedback systems, navigation patterns, and cognitive load management. Intermediate modules introduce micro-interactions, behavioral design concepts, and experimentation methods such as A/B testing to refine usability outcomes. In the advanced segment, participants evaluate performance metrics, optimize conversion flows, and apply data-driven refinement strategies to continuously improve user satisfaction. This course enables designers to move beyond static interfaces and create adaptive, responsive experiences that deliver measurable improvements in product performance.', 'インタラクションデザインとエクスペリエンスの最適化は、デジタルエンゲージメントを強化する直感的で意味のあるユーザーインタラクションを作成することに焦点を当てています。 基本的なレベルでは、学習者は相互作用の原則、フィードバックシステム、ナビゲーションパターン、および認知負荷管理を探ります。 中間モジュールは、マイクロインタラクション、行動設計の概念、およびa/Bテストなどの実験方法を導入して、ユーザビリティの結果を改善します。 Advancedセグメントでは、参加者はパフォーマンスメトリックを評価し、コンバージョンフローを最適化し、データ駆動型の洗練戦略を適用してユーザー満足度を継続的に向上させます。 このコースでは、設計者は静的なインターフェイスを超えて、製品パフォーマンスの測定可能な改善を提供する適応性のある応答性の高い体験を作', 'Interaction Design & Experience Optimization Course', 'Learn interaction design principles and optimization techniques to improve usability, engagement, and product performance.', 'interaction design course, experience optimization, user engagement strategies, digital usability training, product optimization', 'storage/photos/products/14.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 4, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(15, 'DevOps Principles & CI/CD Implementation', 'DevOpsの原則とCI/CDの実装', 'devops-principles-cicd-implementation', 'This course introduces DevOps culture, automation workflows, and CI/CD pipeline implementation. Learners understand how continuous integration and delivery improve deployment efficiency and software reliability. The program emphasizes collaboration, automation, and scalable operational practices.', 'このコースでは、DevOpsの文化、自動化ワークフロー、CI/CDパイプラインの実装について紹介します。 学習者から継続的インテグレーション、納期を改善導入効率およびソフトウェア信頼性です。 このプログラムは、コラボレーション、自動化、およびスケーラブルな運用慣行を強調しています。', 'DevOps Principles & CI/CD Implementation delivers a structured understanding of modern software delivery practices. The foundational level introduces DevOps culture, collaboration models, and the lifecycle of application deployment. As learners progress, they design continuous integration workflows, automate testing environments, and configure delivery pipelines to reduce friction between development and operations. At the advanced level, participants implement monitoring systems, optimize release cycles, and strengthen reliability through automation governance and infrastructure-as-code practices. This course prepares professionals to streamline deployment processes while maintaining security, scalability, and operational resilience.', 'DevOpsの原則とCI/CDの実装により、最新のソフトウェア配信プラクティスの構造化された理解が提供されます。 基本レベルでは、DevOpsの文化、コラボレーションモデル、およびアプリケーションのデプロイのライフサイクルが紹介されます。 学習者が進むにつれて、継続的な統合ワークフローを設計し、テスト環境を自動化し、開発と運用の間の摩擦を減らすために配信パイプラインを構成します。 レベルの高さは、参加者は実施をモニタリングシステムの最適化をリサイクルの強化信頼性の自動化によるガバナンス-インフラとしてのコードです。 このコースを専業展開プロセスを維持しつつセキュリティ性、拡張性、業務の過去最高を更新いたしました。■', 'DevOps Principles & CI/CD Implementation Course', 'Understand DevOps culture, CI/CD pipelines, and automation strategies to improve software deployment and delivery efficiency.', 'devops course, cicd training, continuous integration delivery, automation in devops, software deployment training', 'storage/photos/products/15.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 5, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(16, 'Agile & Scrum Project Management', 'アジャイルとスクラムのプロジェクト管理', 'agile-scrum-project-management', 'This course covers Agile principles and Scrum methodology for effective project delivery. Learners explore sprint planning, backlog management, team collaboration, and iterative development cycles. The focus is on delivering value efficiently while maintaining adaptability in dynamic environments.', 'このコースでは、効果的なプロジェクト配信のためのアジャイル原則とスクラム方法論をカバーしています。 学習者は、スプリント計画、バックログ管理、チームコラボレーション、反復的な開発サイクルを探ります。 焦点は動的環境の適応性を維持している間価値を効率的に提供することにある。', 'Agile & Scrum Project Management offers a practical framework for delivering projects in iterative and adaptive environments. At the beginner stage, learners explore Agile values, Scrum roles, and ceremony structures that define collaborative development cycles. Intermediate modules focus on backlog refinement, sprint forecasting, velocity tracking, and stakeholder communication strategies. In the advanced section, participants address scaling Agile across multiple teams, managing cross-functional dependencies, and implementing performance metrics to sustain continuous improvement. The course enables professionals to foster transparency, accountability, and adaptability in complex software initiatives.', 'アジャイルとスクラムのプロジェクト管理は、反復的で適応的な環境でプロジェクトを提供するための実用的なフレームワークを提供します。 初心者の段階では、学習者はアジャイルの価値観、スクラムの役割、共同開発サイクルを定義する儀式の構造を探求します。 中間モジュールは、バックログの改良、スプリント予測、速度追跡、および利害関係者のコミュニケーション戦略に焦点を当てています。 詳細セクションでは、参加者は、複数のチーム間でアジャイルをスケーリングし、機能横断的な依存関係を管理し、継続的な改善を維持するためのパフォーマンスメトリックを実装することに取り組んでいます。 このコースは、専門家が複雑なソフトウェアイニシアチブにおける透明性、説明責任、適応性を促進することを可能にします。', 'Agile & Scrum Project Management Course', 'Learn Agile frameworks and Scrum methodologies including sprint planning, backlog management, and team collaboration.', 'agile course, scrum training, project management agile, sprint planning, software development management', 'storage/photos/products/16.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 5, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(17, 'Cloud-Native Deployment & Infrastructure Automation', 'クラウドネイティブの導入とインフラストラクチャの自動化', 'cloud-native-deployment-infrastructure-automation', 'This course teaches cloud-native architecture, containerization, and infrastructure automation techniques. Learners gain insight into scalable deployment models and modern DevOps cloud practices. The emphasis is on building resilient, efficient, and scalable application environments.', 'このコースでは、クラウドネイティブアーキテクチャ、コンテナ化、およびインフラストラクチャオートメーションテクニックを学びます。 学習者は、スケーラブルなデプロイメントモデルと最新のDevOpsクラウドプラクティスについての洞察を得ることができます。 重点は、弾力性のある、効率的でスケーラブルなアプリケーション環境を構築することです。', 'Cloud-Native Deployment & Infrastructure Automation provides a progressive pathway into modern cloud architecture and scalable deployment models. The foundational phase introduces containerization concepts, microservices architecture, and distributed system fundamentals. At the intermediate level, learners configure orchestration platforms, manage infrastructure-as-code environments, and automate provisioning processes. In advanced modules, participants design resilient cloud strategies, optimize performance under dynamic loads, and implement governance standards for secure and efficient operations. The course prepares technology professionals to build flexible infrastructures that support rapid innovation and long-term scalability.', 'クラウドネイティブのデプロイメントとインフラストラクチャの自動化は、最新のクラウドアーキテクチャとスケーラブルなデプロイモデルへの進歩的な経路を提供します。 基礎段階では、コンテナ化の概念、マイクロサービスアーキテクチャ、分散システムの基礎を紹介します。 中級レベルでは、学習者はオーケストレーションプラットフォームの構成、コードとしてのインフラストラクチャ環境の管理、およびプロビジョニングプロセスの自動化を行います。 高度なモジュールでは、参加者は弾力性のあるクラウド戦略を設計し、動的負荷の下でパフォーマンスを最適化し、安全で効率的な運用のためのガバ このコースでは、急速なイノベーションと長期的な拡張性をサポートする柔軟なインフラストラクチャを構築するための技術の専門家を準備します。', 'Cloud-Native Deployment & Infrastructure Automation', 'Master cloud-native architecture, containerization, and infrastructure automation for scalable application deployment.', 'cloud native course, infrastructure automation, containerization training, devops cloud deployment, scalable architecture', 'storage/photos/products/17.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 5, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL),
(18, 'Technology Leadership & Engineering Management', 'テクノロジー-リーダーシップ＆エンジニアリング-マネジメント', 'technology-leadership-engineering-management', 'This course develops leadership and management skills for technology-driven organizations. Learners explore team scaling, performance management, and strategic technology planning. The program focuses on aligning engineering execution with long-term business and innovation goals.', 'このコースでは、技術主導型の組織のためのリーダーシップと管理スキルを開発します。 学習者は、チームのスケーリング、パフォーマンス管理、および戦略的な技術計画を探ります。 このプログラムは、エンジニアリングの実行を長期的なビジネスとイノベーションの目標と整合させることに焦点を当てています。', 'Technology Leadership & Engineering Management develops the capabilities required to lead high-performing technical organizations. At the foundational stage, learners explore leadership principles, communication frameworks, and team structure models. Intermediate topics focus on performance evaluation, hiring strategy, cross-functional collaboration, and operational planning. In the advanced segment, participants address organizational scaling, innovation management, strategic budgeting, and long-term technology vision alignment. The program equips current and aspiring leaders with the strategic insight and managerial discipline necessary to guide engineering teams through growth, complexity, and technological transformation.', 'テクノロジーリーダーシップ&エンジニアリングマネジメントは、高性能な技術組織をリードするために必要な能力を開発します。 基礎段階では、学習者はリーダーシップの原則、コミュニケーションフレームワーク、およびチーム構造モデルを探ります。 中間的なトピックは、パフォーマンス評価、雇用戦略、機能横断的なコラボレーション、運用計画に焦点を当てています。 上級部門では、参加者は組織のスケーリング、イノベーション管理、戦略的な予算編成、および長期的な技術ビジョンの調整に取り組んでいます。 このプログラムは、成長、複雑さ、技術変革を通じてエンジニアリングチームを導くために必要な戦略的洞察と経営規律を現在および意欲的なリーダーに', 'Technology Leadership & Engineering Management Course', 'Build leadership and management skills to scale engineering teams, manage performance, and drive technology strategy.', 'engineering management course, technology leadership training, tech team management, software leadership skills, engineering strategy', 'storage/photos/products/18.webp', 1, 'M', 'default', 'active', 0.00, 0.00, 0.00, 0.00, NULL, NULL, NULL, 5, NULL, NULL, 0, NULL, NULL, 0, 'A', 'A', NULL, NULL);
INSERT INTO `product_levels` (`id`, `course_id`, `skill_level`, `skill_level_jp`, `purpose`, `purpose_jp`, `learn_info`, `learn_info_jp`, `outcome`, `outcome_jp`, `price`, `price_jp`, `price_hk`, `created_at`, `updated_at`) VALUES
(1, 1, 'Beginner', 'ビギナー', 'Understand basic programming logic syntax and how programs execute', '基本的なプログラミングロジック構文とプログラムの実行方法を理解する', 'Understand variables data types and operators.\nLearn control structures (conditions, loops).\nWrite simple functions and programs.\nUnderstand how code executes step by step.\nDebug basic syntax and logic errors\n', '変数のデータ型と演算子を理解します。\r\n\n制御構造（条件、ループ）を学びます。\r\n\n簡単な関数とプログラムを書く。\r\n\nコードがどのように段階的に実行されるかを理解します。\r\n\n基本的な構文エラーとロジックエラーのデバッグ', 'Write simple programs using core programming concepts', 'コアプログラミングの概念を使用して簡単なプログラムを書く', 30.00, 5000.00, 240.00, NULL, NULL),
(2, 1, 'Intermediate', '中級', 'Apply common programming structures to build functional applications', '一般的なプログラミング構造を適用して機能アプリケーションを構築する', 'Use functions and modular programming techniques.  Work with arrays lists and data collections.  Implement input and output handling.  Apply basic error handling.  Build small structured applications', '関数とモジュラープログラミング技術を使用する\n配列リストとデータコレクションを操作する\n入力と出力の処理を実装する\n基本的なエラー処理を適用する\n小さな構造化されたアプリケーションを構築する', 'Develop structured applications using modular programming techniques', 'モジュラープログラミング技術を使用した構造化アプリケーションの開発', 120.00, 20000.00, 960.00, NULL, NULL),
(3, 1, 'Advanced', 'アドバンスド', 'Write clean maintainable and efficient code using best practices', 'ベストプラクティスを使用してクリーンな保守可能で効率的なコードを書く', 'Apply object oriented programming principles.  Write clean readable and maintainable code.  Implement debugging and testing practices.  Understand basic algorithms and data structures.  Optimize code structure and organization', 'オブジェクト指向プログラミングの原則を適用する\nクリーンで読みやすく保守可能なコードを書く\nデバッグとテストの実践を実装する\n基本的なアル', 'Produce clean maintainable and efficient code following best practices', 'ベストプラクティスに従って、クリーンで保守可能で効率的なコードを生成する', 300.00, 50000.00, 2400.00, NULL, NULL),
(4, 1, 'Expert', '専門家', 'Design scalable software systems with architectural and performance awareness', 'アーキテクチャとパフォーマンスを意識したスケーラブルなソフ', 'Understand software architecture fundamentals.  Apply design principles (modularity, separation of concerns, SOLID basics).  Improve performance and scalability considerations.  Manage version control workflows.  Develop enterprise ready coding practices', 'ソフトウェアアーキテクチャの基礎を理解する。\r\n  設計原則（モジュール性、懸念の分離、固体の基本）を適用します。\r\n  パフォーマンスとスケーラビリティの考慮事項を改善します。\r\n  バージョン管理のワークフローを管理します。\r\n  エンタープライズ対応のコーディング手法を開発する', 'Design scalable software solutions with architectural awareness', 'アーキテクチャを意識したスケーラブルなソフトウェアソリューションの設計', 900.00, 150000.00, 7200.00, NULL, NULL),
(5, 2, 'Beginner', 'ビギナー', 'Understand foundational web concepts and how web applications function', '基本的なweb概念とwebアプリケーションの機能を理解する', 'Understand how the web works (HTTP, browsers, servers).  Build basic HTML CSS page structures.  Learn client server communication basics.  Create simple static web pages.  Understand web hosting fundamentals', 'Webがどのように機能するかを理解します（HTTP、ブラウザ、サーバー）。\r\n  基本的なHTML CSSページ構造を構築します。\r\n  クライアントサーバー通信の基本を学びます。\r\n  単純な静的webページを作成します。\r\n  Webホスティングの基礎を理解する', 'Build basic web pages and understand web application fundamentals', '基本的なwebページを構築し、webアプリケーションの基礎を理解する', 65.00, 10000.00, 520.00, NULL, NULL),
(6, 2, 'Intermediate', '中級', 'Develop frontend and backend components for dynamic web applications', '動的webアプリケーション用のフロントエンドおよびバックエンドコンポーネントの開発', 'Develop interactive frontend interfaces.  Implement basic backend logic.  Connect applications to databases.  Handle form submissions and routing.  Apply basic authentication concepts', '開発型のフロントエンドフェース-実施の基本ロジックバックエンド\n接続用のデータベース\n扱う形で応募作品およびルーティングして出力することができます基本的な認証の概念', 'Develop functional frontend and backend components', '機能的なフロントエンドとバックエンドコンポーネントの開発', 200.00, 30000.00, 1600.00, NULL, NULL),
(7, 2, 'Advanced', 'アドバンスド', 'Build full stack applications with APIs databases and deployment workflows', 'Apiデータベースとデプロイワークフローを使用したフルスタックアプリケーションの構築', 'Build full stack applications integrating frontend and backend.  Develop RESTful APIs.  Implement database design and management.  Apply deployment workflows and version control.  Manage application state and performance optimization', 'フロントエンドとバックエンドを統合したフルスタックアプリケーションの構築\nRESTful Apiの開発\nデータベース設計と管理の実装\nデプロイワークフローとバージョ', 'Create and deploy full stack web applications', 'フルスタックwebアプリケーションの作成と展開', 450.00, 75000.00, 3600.00, NULL, NULL),
(8, 2, 'Expert', '専門家', 'Design secure scalable and high performance web architectures', '安全なスケーラブルで高性能なwebアーキテクチャを設計', 'Design scalable web architectures.  Implement advanced security practices (authentication, authorization, encryption).  Optimize performance and load handling.  Apply cloud deployment and CI/CD pipelines.  Build enterprise ready web systems', 'スケーラブルなwebアーキテクチャを設計します。\r\n  高度なセキュリティ慣行(認証、承認、暗号化)を実装します。\r\n  性能を最適化および負荷ります。\r\n  適用クラウドに展開、CI/CDパイプライン  構築する事で既にwebシステム', 'Design secure scalable and high performance web systems', '安全でスケーラブルで高性能なwebシステムの設計', 1300.00, 200000.00, 10400.00, NULL, NULL),
(9, 3, 'Beginner', 'ビギナー', 'Understand the importance of software testing and quality assurance fundamentals', 'ソフトウェアテストと品質保証の基礎の重要性を理解する', 'Understand software defects and bug lifecycle.  Learn importance of quality assurance.  Identify different types of testing (unit, integration, system).  Write simple test cases.  Understand manual testing fundamentals', 'ソフトウェアの欠陥とバグのライフサイクルを理解する。\r\n  品質保証の重要性を学ぶ。\r\n  さまざまなタイプのテスト（ユニット、統合、システム）を特定します。\r\n  簡単なテストケースを書く。\r\n  手動テストの基礎を理解する', 'Understand core software testing principles and quality fundamentals', 'コアソフトウェアテストの原則と品質の基礎を理解する', 65.00, 10000.00, 500.00, NULL, NULL),
(10, 3, 'Intermediate', '中級', 'Apply structured testing techniques to identify and prevent defects', '構造化された試験技術を適用して欠陥を特定し、防止する', 'Create structured test cases and test plans.  Perform functional and regression testing.  Apply boundary value and edge case analysis.  Document defects effectively.  Collaborate with development teams for quality improvement', '構造化されたテストケースとテスト計画を作成する\n機能テストと回帰テストを実行する\n境界値とエッジケース分析を適用する\n欠陥を効果的に文書化', 'Develop structured testing processes to improve application reliability', 'アプリケーションの信頼性を向上させる構造化されたテストプロセスを開発する', 200.00, 30000.00, 1600.00, NULL, NULL),
(11, 3, 'Advanced', 'アドバンスド', 'Implement automated testing within modern development workflows', '最新の開発ワークフロー内で自動テストを実装する', 'Implement automated unit and integration tests.  Use testing frameworks and tools.  Integrate testing into CI/CD pipelines.  Measure code coverage and quality metrics.  Apply test driven development principles', '自動化されたユニットテストと統合テストを実装します。\r\n  テストフレームワークとツールを使用します。\r\n  テストをCI/CDパイプラインに統合します。\r\n  コードカバレッジと品質指標を測定します。\r\n  テスト駆動開発の原則を適用する', 'Implement automated testing within development workflows', '開発ワークフロー内での自動テストの実装', 650.00, 100000.00, 5200.00, NULL, NULL),
(12, 3, 'Expert', '専門家', 'Design enterprise level testing strategies and continuous quality systems', '企業レベルのテスト戦略と継続的な品質システムの設計', '. Design enterprise testing strategies. Implement performance and security testing. Build scalable automated testing frameworks. Establish continuous integration and quality assurance systems. Ensure long term software reliability and maintainability standards', 'エンタープライズテスト戦略の設計\nパフォーマンスとセキュリティテストの実装\nスケーラブルな自動testiの構築', 'Design enterprise grade quality assurance and continuous testing systems', '企業の等級の品質保証および連続的な試験制度を設計して下さい', 1500.00, 225000.00, 12000.00, NULL, NULL),
(13, 4, 'Beginner', 'ビギナー', 'Understand basic data types structures and fundamental analysis concepts', '基本的なデータ型の構造と基本的な分析の概念を理解する', 'Understand different data types (structured, unstructured, quantitative, qualitative).  Organize and clean basic datasets.  Use spreadsheets or basic tools for data handling.  Perform simple calculations and summaries.  Interpret basic descriptive statistics', 'さまざまなデータ型（構造化、非構造化、定量、定性的）を理解する。\r\n  基本的なデータセットを整理してクリーンにします。\r\n  データ処理にはスプレッドシートまたは基本ツールを使用します。\r\n  簡単な計算と要約を実行します。\r\n  基本記述統計の解釈', 'Organize and interpret basic datasets effectively', '基本的なデータセットを効果的に整理して解釈する', 120.00, 20000.00, 960.00, NULL, NULL),
(14, 4, 'Intermediate', '中級', 'Perform structured data analysis and generate meaningful reports', '構造化データ分析を実行し、意味のあるレポートを生成する', 'Apply filtering sorting and grouping techniques.  Generate basic reports and dashboards.  Perform comparative analysis.  Use charts and simple visualizations.  Identify basic trends and anomalies', 'フィルタリングのソートとグループ化技術の適用\n基本的なレポートとダッシュボードの生成\n比較分析の実行\nチャートと簡単な視覚化の使用\n基本的な傾向と', 'Generate structured reports and identify meaningful patterns', '構造化レポートを生成し、意味のあるパターンを特定', 375.00, 62500.00, 3000.00, NULL, NULL),
(15, 4, 'Advanced', 'アドバンスド', 'Identify trends patterns and insights using analytical and visualization techniques', '分析および可視化技術を使用して、傾向パターンと洞察を特定する', 'Apply intermediate statistical concepts.  Create advanced visualizations.  Identify correlations and performance patterns.  Use data analysis tools and query techniques.  Translate data findings into actionable insights', '中間統計概念の適用\n高度な視覚化の作成\n相関とパフォーマンスパターンの特定\nデータ分析ツールとクエリ手法の使用\nデータの調査結果を実用的なインサイト', 'Analyze trends and visualize insights to support decisions', '傾向を分析し、洞察を視覚化して意思決定を支援', 900.00, 150000.00, 7200.00, NULL, NULL),
(16, 4, 'Expert', '専門家', 'Apply data driven insights strategically to improve organizational performance', 'データ駆動型の洞察を戦略的に適用して組織のパフォーマンスを向上させる', 'Design data driven decision frameworks.  Apply predictive and performance analysis methods.  Integrate multiple data sources for strategic insights.  Evaluate business performance metrics.  Support organizational planning using analytical evidence', 'データドリブンな意思決定フレームワークを設計する\n予測およびパフォーマンス分析方法を適用する\n戦略的洞察のための複数のデータソースを統合する\nビジネスパフォーマンスメトリックを評価する\n分析的証拠を使用して組織計画をサポートする', 'Apply strategic data analysis to improve business performance and planning', '戦略的なデータ分析を適用して、業績と計画を改善する', 2000.00, 300000.00, 16000.00, NULL, NULL),
(17, 5, 'Beginner', 'ビギナー', 'Understand core automation concepts and identify repetitive business tasks', '自動化のコア概念を理解し、反復的なビジネスタスクを特定する', 'Understand fundamentals of automation and scripting.  Identify repetitive manual tasks.  Learn basic scripting syntax and logic.  Automate simple file and data operations.  Improve personal workflow efficiency', '自動化とスクリプトの基礎を理解する\n反復的な手動タスクを特定する\n基本的なスクリプト構文とロジックを学ぶ\n簡単なファイルとデータ操作を自動化する\n個人的なワークフローの効率を向上させる', 'Identify automation opportunities to reduce repetitive tasks', '反復的なタスクを減らすための自動化の機会を特定する', 200.00, 30000.00, 1600.00, NULL, NULL),
(18, 5, 'Intermediate', '中級', 'Create simple scripts to automate routine workflows', 'ルーチンワークフローを自動化するための簡単なスクリプトを作成する', 'Write scripts to process data and generate reports.  Automate email and notification workflows.  Integrate scripts with common business tools.  Handle input validation and error control.  Test and debug automation scripts', 'データを処理し、レポートを生成するためのスクリプトを書く\n電子メールと通知のワークフローを自動化\n一般的なビジネスツールとスクリプトを統合\n入力の検証とエラー制御を処理する\nテストとデバッグの自動化スクリプト', 'Build functional scripts to streamline daily business workflows', '毎日のビジネスワークフローを合理化するための機能的なスクリプトを構築', 500.00, 80000.00, 4000.00, NULL, NULL),
(19, 5, 'Advanced', 'アドバンスド', 'Design integrated automation solutions across systems and processes', 'システムとプロセス全体で統合された自動化ソリューションを設計する', 'Design cross system workflow automation.  Integrate APIs and external services.  Optimize process efficiency using automation tools.  Implement scheduling and task orchestration.  Ensure security and reliability in automated processes', 'システム間ワークフローの自動化の設計\nApiと外部サービスの統合\n自動化ツールを使用したプロセス効率の最適化\nスケジューリングとタスクオーケストレーション', 'Design integrated automation systems across multiple platforms', '複数のプラットフォーム間で統合された自動化システムを設計する', 1300.00, 200000.00, 10400.00, NULL, NULL),
(20, 5, 'Expert', '専門家', 'Develop scalable enterprise automation strategies and governance models', 'スケーラブルなエンタープライズ自動化戦略とガバナンスモデルの開発', 'Develop enterprise automation frameworks.  Implement monitoring and logging systems.  Design scalable automation architectures.  Apply governance and compliance standards.  Optimize automation strategies for long term operational efficiency', 'エンタープライズ自動化フレームワークの開発\n監視およびロギングシステムの実装\nスケーラブルな自動化アーキテクチャの設計\nガバナンスとコンプ', 'Implement scalable and governed automation strategies for enterprise efficiency', '企業の効率化のためのスケーラブルで管理された自動化戦略の実装', 3500.00, 500000.00, 28000.00, NULL, NULL),
(21, 6, 'Beginner', 'ビギナー', 'Understand fundamental AI tools and everyday applications', '基本的なAIツールと日常のアプリケーションを理解する', 'Understand basic AI concepts and terminology.  Explore common AI powered tools.  Use AI for content generation and research assistance.  Apply AI for simple data insights.  Recognize limitations of AI systems', '基本的なAIの概念と用語を理解する\n一般的なAI搭載ツールを探索する\nコンテンツ生成と研究支援のためにAIを使用する\n簡単なデータ洞察のためにAIを適用する\nAIシステムの制限を認識する', 'Use AI tools effectively for everyday productivity tasks', '日常の生産性タスクにAIツールを効果的に使用する', 200.00, 30000.00, 1600.00, NULL, NULL),
(22, 6, 'Intermediate', '中級', 'Apply AI tools to improve productivity and analytical tasks', 'AIツールを適用して生産性と分析タスクを向上させる', 'Use AI for workflow automation and productivity improvement.  Apply AI in data analysis and reporting.  Customize prompts for better output quality.  Evaluate AI output accuracy.  Improve task efficiency using AI tools', 'ワークフローの自動化と生産性向上にAIを使用\nデータ分析とレポートにAIを適用\nより良い出力品質のためのプロンプトをカスタマイズ\nAI出力精度を評価\nAIツールを使用してタスク効率を向上させる', 'Apply AI solutions to enhance business workflows and analysis', 'AIソリューションを適用してビジネスワークフローと分析を強化', 650.00, 100000.00, 5200.00, NULL, NULL),
(23, 6, 'Advanced', 'アドバンスド', 'Integrate AI solutions into business workflows and processes', 'AIソリューションをビジネスワークフローとプロセスに統合', 'Integrate AI into business processes and decision support systems.  Connect AI tools with existing platforms.  Optimize workflows using intelligent automation.  Measure AI driven productivity gains.  Manage AI related risks and constraints', 'ビジネスプロセスと意思決定支援システムへのAIの統合\nAIツールと既存のプラットフォームとの接続\nインテリジェントな自動化を使用してワークフローを最適化\nAI主導の生産性向上を測定\nAI関連のリスクと制約を管理する', 'Integrate AI strategically within operational processes', '運用プロセス内でAIを戦略的に統合', 1500.00, 225000.00, 12000.00, NULL, NULL),
(24, 6, 'Expert', '専門家', 'Design responsible and strategic AI adoption frameworks for organizations', '組織のための責任ある戦略的なAI導入フレームワークの設計', 'Develop organizational AI adoption strategies.  Implement responsible AI usage guidelines.  Evaluate ethical and compliance considerations.  Build scalable AI integration models.  Create long term value through strategic AI deployment', '組織的なAI導入戦略の策定\n責任あるAI利用ガイドラインの実装\n倫理的およびコンプライアンスに関する考慮事項の評価\nスケーラブルなAI統合モデ', 'Lead responsible and scalable AI adoption for organizational growth', '組織の成長のための責任あるスケーラブルなAIの採用をリード', 3500.00, 500000.00, 28000.00, NULL, NULL),
(25, 7, 'Beginner', 'ビギナー', 'Understand fundamental IT infrastructure components including servers and networks', 'サーバーやネットワークを含む基本的なITインフラストラクチャコンポーネントを理解する', 'Understand basic IT components (servers, storage, networks).  Learn how operating systems function.  Identify hardware and software roles.  Understand basic networking concepts.  Recognize infrastructure security fundamentals', '基本的なITコンポーネント(サーバー、ストレージ、ネットワーク)を理解します。\r\n  オペレーティングシステムがどのように機能するかを学びます。\r\n  ハードウェアとソフトウェアの役割を特定します。\r\n  基本的なネットワークの概念を理解します。\r\n  インフラストラクチャのセキュリティの基礎を認識する', 'Understand core IT infrastructure components and system functions', 'コアITインフラストラクチャコンポーネントとシステム機能を理解する', 300.00, 50000.00, 2400.00, NULL, NULL),
(26, 7, 'Intermediate', '中級', 'Manage and maintain core system operations effectively', '基幹システムの運用を効率的に管理-維持する', 'Manage server configuration and user access.  Monitor system performance.  Perform basic troubleshooting.  Implement backup procedures.  Maintain network connectivity and stability', 'サーバー構成とユーザーアクセスの管理\nシステムパフォーマンスの監視\n基本的なトラブルシューティングの実行\nバックアップ手順の実装\nネットワー', 'Manage and maintain reliable IT operations', '信頼性の高いIT運用の管理と維持', 800.00, 120000.00, 6400.00, NULL, NULL),
(27, 7, 'Advanced', 'アドバンスド', 'Optimize infrastructure performance reliability and availability', 'インフラストラクチャのパフォーマンスの信頼性と可用性を最適化', 'Optimize system performance and resource allocation.  Implement redundancy and failover mechanisms.  Strengthen infrastructure security controls.  Manage virtualization environments.  Improve reliability through monitoring tools', 'システムパフォーマンスとリソース割り当ての最適化\n冗長性とフェールオーバーメカニズムの実装\nインフラストラクチャセキュリティ制御の強化\n仮想化環境の管理\n監視ツールによる信頼性の向上', 'Optimize infrastructure performance and availability', 'インフラストラクチャのパフォーマンスと可用性の最適化', 2000.00, 300000.00, 16000.00, NULL, NULL),
(28, 7, 'Expert', '専門家', 'Design and plan enterprise grade IT infrastructure environments', 'エンタープライズグレードのITインフラストラクチャ環境の設計と計画', 'Design scalable infrastructure architectures.  Plan capacity and disaster recovery strategies.  Integrate cloud and on premises systems.  Apply enterprise security frameworks.  Build high availability and resilient IT environments', 'スケーラブルなインフラストラクチャアーキテクチャの設計\n容量と災害復旧戦略の計画\nクラウドとオンプレミスシステムの統合\nエンタープライズセキュ', 'Design enterprise grade scalable and resilient IT environments', 'エンタープライズグレードの拡張性と弾力性のあるIT環境を設計', 5000.00, 700000.00, 40000.00, NULL, NULL),
(29, 8, 'Beginner', 'ビギナー', 'Understand core cloud computing concepts and service models', 'コアクラウドコンピューティングの概念とサービスモデルを理解する', 'Understand cloud service models (IaaS, PaaS, SaaS).  Learn deployment models (public, private, hybrid).  Identify core cloud components.  Explore virtualization basics.  Recognize cloud security fundamentals', 'クラウドサービスモデル（IaaS、PaaS、SaaS）を理解します。\r\n  展開モデル(パブリック、プライベート、ハイブリッド)を学習します。\r\n  コアクラウドコンポーネントを特定します。\r\n  仮想化の基本を探ります。\r\n  クラウドのセキュリティの基礎を理解する', 'Understand foundational cloud computing concepts and models', '基本的なクラウドコンピューティングの概念とモデルを理解する', 300.00, 50000.00, 2400.00, NULL, NULL),
(30, 8, 'Intermediate', '中級', 'Deploy and manage cloud resources efficiently', 'クラウドリソースの効率的な展開と管理', 'Deploy virtual machines and storage resources.  Configure networking in the cloud.  Manage user access and permissions.  Monitor cloud usage and performance.  Apply basic cost management principles', '仮想マシンとストレージリソースの展開\nクラウドでのネットワークの構成\nユーザーアクセスと権限の管理\nクラウドの使用状況とパフォーマンスの監視\n基本的なコスト管理の原則を適用する', 'Deploy and manage cloud infrastructure resources effectively', 'クラウドインフラストリソースの効果的な展開と管理', 900.00, 150000.00, 7200.00, NULL, NULL),
(31, 8, 'Advanced', 'アドバンスド', 'Design scalable secure and resilient cloud architectures', 'スケーラブルでセキュアで弾力性のあるクラウドアーキテクチャの設計', 'Design scalable and highly available cloud architectures.  Implement load balancing and auto scaling.  Strengthen cloud security configurations.  Apply backup and disaster recovery strategies.  Optimize cloud resource utilization', 'スケーラブルで可用性の高いクラウドアーキテクチャの設計\n負荷分散とauto scalingの実装\nクラウドセキュリティ構成の強化\nバックアップとディザスタリカバリ戦略の適用\nクラウドリソースの使用率の最適化', 'Design secure scalable and resilient cloud architectures', 'セキュアでスケーラブルで弾力性のあるクラウドアーキテクチャの設計', 2500.00, 375000.00, 20000.00, NULL, NULL),
(32, 8, 'Expert', '専門家', 'Implement multi cloud strategies with governance and cost optimization', 'ガバナンスとコストの最適化によるマルチクラウド戦略の実装', 'Develop multi cloud management strategies.  Implement governance and compliance frameworks.  Optimize cost through monitoring and automation.  Integrate DevOps and CI/CD pipelines.  Build enterprise grade secure cloud environments', 'マルチクラウド管理戦略を開発します。\r\n  ガバナンスとコンプライアンスのフレームワークを実装します。\r\n  監視と自動化を通じてコストを最適化します。\r\n  DevOpsとCI/CDパイプラインを統合します。\r\n  エンタープライズグレードのセキュアなクラウド環境を構築', 'Lead enterprise multi cloud strategy with governance and cost control', 'ガバナンスとコスト管理を備えたエンタープライズマルチクラウド戦略をリード', 5000.00, 700000.00, 40000.00, NULL, NULL),
(33, 9, 'Beginner', 'ビギナー', 'Understand core DevOps principles and modern development workflows', 'DevOpsのコア原則と最新の開発ワークフローを理解する', 'Understand DevOps culture and collaboration principles.  Learn software development lifecycle basics.  Explore version control workflows.  Identify benefits of CI/CD practices.  Recognize importance of automation', 'DevOpsの文化とコラボレーションの原則を理解する。\r\n  ソフトウェア開発ライフサイクルの基本を学びます。\r\n  バージョン管理のワークフローを確認します。\r\n  CI/CDプラクティスの利点を特定する。\r\n  自動化の重要性を認識する', 'Understand DevOps principles and collaborative development workflows', 'DevOpsの原則と共同開発ワークフローを理解する', 375.00, 62500.00, 3000.00, NULL, NULL),
(34, 9, 'Intermediate', '中級', 'Build and manage continuous integration and continuous delivery pipelines', '継続的な統合と継続的な配信パイプラインの構築と管理', 'Build basic CI pipelines for automated testing.  Configure CD pipelines for deployments.  Integrate version control with build systems.  Manage artifacts and releases.  Monitor pipeline performance', '自動テスト用の基本的なCIパイプラインの構築\n展開用のCDパイプラインの構成\nバージョン管理とビルドシステムの統合\n成果物とリリースの管理\nパイ', 'Build and manage functional CI/CD pipelines', 'の構築-管理機能CI/CDパイプライン', 900.00, 150000.00, 7200.00, NULL, NULL),
(35, 9, 'Advanced', 'アドバンスド', 'Implement automation and infrastructure as code practices', '自動化とインフラストラクチャをコードプラクティスとして実装する', 'Implement infrastructure as code tools.  Automate environment provisioning.  Apply containerization concepts.  Integrate security into pipelines (DevSecOps basics).  Improve reliability through automated testing frameworks', 'コードツールとしてのインフラストラクチャの実装\n環境プロビジョニングの自動化\nコンテナ化の概念の適用\nパイプラインへのセキュリティの統合(DevSecOpsの基礎)\n自動化されたテストフレームワークによる信頼性の向上', 'Automate infrastructure and deployment processes effectively', 'インフラストラクチャと展開プロセスを効果的に自動化', 2000.00, 300000.00, 16000.00, NULL, NULL),
(36, 9, 'Expert', '専門家', 'Scale DevOps frameworks aligned with organizational and business objectives', '組織とビジネスの目標に合わせたDevOpsフレームワークの規模を拡大', 'Design scalable DevOps architectures.  Implement monitoring and observability systems.  Optimize deployment frequency and stability.  Align DevOps practices with business KPIs.  Establish enterprise governance and continuous improvement models', 'スケーラブルなDevOpsアーキテクチャの設計\n監視および可観測性システムの実装\n展開頻度と安定性の最適化\nDevOpsプラクティスとビジネスKpiの整合性\nエンタープ', 'Lead scalable DevOps implementations aligned with business performance goals', 'ビジネスパフォーマンスの目標に沿ったスケーラブルなDevOps実装をリード', 5000.00, 700000.00, 40000.00, NULL, NULL),
(37, 10, 'Beginner', 'ビギナー', 'Understand fundamental cybersecurity concepts and common threat landscapes', '基本的なサイバーセキュリティの概念と一般的な脅威の状況を理解する', 'Understand common cyber threats (malware, phishing, ransomware).  Identify vulnerabilities and attack vectors.  Learn basic security principles (confidentiality, integrity, availability).  Recognize importance of access control.  Practice safe digital behavior', '一般的なサイバー脅威(マルウェア、フィッシング、ランサムウェア)を理解します。\r\n  脆弱性と攻撃ベクトルを特定します。\r\n  基本的なセキュリティ原則（機密性、完全性、可用性）を学びます。\r\n  アクセス制御の重要性を認識する。\r\n  安全なデジタル行動を実践する', 'Recognize cybersecurity threats and apply basic protective measures', 'サイバーセキュリティの脅威を認識し、基本的な保護対策を適用する', 200.00, 30000.00, 1600.00, NULL, NULL),
(38, 10, 'Intermediate', '中級', 'Apply practical security controls to protect systems and data', '実用的なセキュリティ制御を適用してシステムとデータを保護する', 'Implement authentication and authorization controls.  Configure firewalls and endpoint protection.  Apply encryption fundamentals.  Conduct basic vulnerability assessments.  Monitor systems for suspicious activity', '認証および承認制御の実装\nファイアウォールとエンドポイント保護の構成\n暗号化の基礎の適用\n基本的な脆弱性評価の実施\n疑わしい活動のためのシ', 'Implement practical security controls to safeguard systems and data', 'システムとデータを保護するための実用的なセキュリティ制御の実装', 650.00, 100000.00, 5200.00, NULL, NULL),
(39, 10, 'Advanced', 'アドバンスド', 'Manage incident response and operational security processes', 'インシデント対応と運用セキュリティプロセスの管理', 'Develop incident response plans.  Perform risk assessments and threat modeling.  Manage security monitoring and logging.  Apply compliance and regulatory requirements.  Strengthen operational security practices', 'インシデント対応計画の策定\nリスク評価と脅威モデリングの実行\nセキュリティ監視とログの管理\nコンプライアンスと規制要件の適用\n運用セキュ', 'Manage incidents and operational security effectively', 'インシデントと運用セキュリティを効果的に管理', 1800.00, 270000.00, 14400.00, NULL, NULL),
(40, 10, 'Expert', '専門家', 'Design enterprise security governance and long term risk management strategies', '企業のセキュリティガバナンスと長期的なリスク管理戦略の設計', 'Design enterprise security governance frameworks.  Implement risk management strategies.  Oversee security audits and policy enforcement.  Integrate security into business continuity planning.  Build long term cybersecurity strategy aligned with organizational goals', 'エンタープライズセキュリティガバナンスフレームワークの設計\nリスク管理戦略の実装\nセキュリティ監査とポリシー施行の監督\nセキュリティを事業継続計画に統合する\n組織の目標に沿った長期的なサイバーセキュリティ戦略を構築する', 'Lead enterprise cybersecurity governance and strategic risk management initiatives', '企業のサイバーセキュリティガバナンスと戦略的リスク管理イニシアチブをリード', 3500.00, 500000.00, 28000.00, NULL, NULL),
(41, 11, 'Beginner', 'ビギナー', 'Understand core user experience principles and user centered design foundations', 'コアユーザーエクスペリエンスの原則とユーザー中心の設計基盤を理解する', 'Understand usability accessibility and human centered design principles.  Learn basics of qualitative and quantitative research methods.  Create user personas.  Develop user journey maps.  Identify user pain points and needs', 'ユーザビリティアクセシビリティと人間中心の設計原則を理解する\n定性的および定量的研究方法の基礎を学ぶ\nユーザペルソナを作成する\nユーザージャーニーマップを開発する\nユーザの痛みのポイントとニーズを特定する', 'Understand foundational UX principles and research methodologies', '基本的なUXの原則と研究方法論を理解する', 200.00, 30000.00, 1600.00, NULL, NULL),
(42, 11, 'Intermediate', '中級', 'Apply research methods to translate user needs into structured design insights', 'ユーザーのニーズを構造化された設計洞察に変換するための研究方法を適用する', 'Plan and conduct user research studies.  Synthesize research findings into insights.  Define clear problem statements.  Prioritize user needs within product constraints.  Translate research into structured design recommendations', 'ユーザー調査研究を計画し、実施する\n研究結果を洞察に合成する\n明確な問題文を定義する\n製品の制約内でユーザーのニーズに優先順位を付ける\n研究を構造化された設計の推奨事項に翻訳する', 'Translate user research into actionable design improvements', 'ユーザー調査を実用的な設計改善に変換する', 450.00, 75000.00, 3600.00, NULL, NULL),
(43, 11, 'Advanced', 'アドバンスド', 'Conduct usability testing and analyze behavioral data for product improvement', 'ユーザビリティテストを実施し、製品改善のための行動データを分析する', 'Conduct structured usability testing sessions.  Analyze behavioral and interaction data.  Measure usability metrics and performance indicators.  Iterate design solutions based on evidence.  Improve clarity and usability through testing feedback', '構造化されたユーザビリティテストセッションの実施\n行動および相互作用データの分析\nユーザビリティメトリックとパフォーマンスインジケータの測定\nエ', 'Conduct usability testing and apply data driven iteration', 'ユーザビリティテストの実施とデータドリブンイテレーションの適用', 1300.00, 200000.00, 10400.00, NULL, NULL),
(44, 11, 'Expert', '専門家', 'Design evidence based user experience strategies aligned with product goals', '製品の目標に沿った、エビデンスに基づくユーザーエクスペリエンス戦略の設計', 'Design comprehensive user research strategies.  Integrate UX insights into product roadmaps.  Align design decisions with business objectives.  Apply data driven UX optimization frameworks.  Lead evidence based user experience initiatives across teams', '包括的なユーザー調査戦略を設計する\nUXインサイトを製品ロードマップに統合する\n設計上の決定をビジネス目標に合わせる\nデータ駆動型UX最適化フレームワークを適用する\nチーム間で証拠ベースのユーザーエクスペリエンスのイニシアチブをリードする', 'Lead structured evidence based UX strategy for digital products', 'デジタル製品のための構造化された証拠ベースのUX戦略をリード', 3000.00, 450000.00, 24000.00, NULL, NULL),
(45, 12, 'Beginner', 'ビギナー', 'Understand core interface design principles and visual hierarchy fundamentals', 'コアインターフェイス設計の原則と視覚的階層の基礎を理解する', 'Understand layout principles and grid systems.  Apply typography systems effectively.  Use spacing and alignment logic.  Establish visual hierarchy.  Design clean and consistent interfaces', 'レイアウトの原則とグリッドシステムを理解する\nタイポグラフィーシステムを効果的に適用する\n間隔と配置ロジックを使用する\n視覚的な階層を確', 'Design structured and visually consistent user interfaces', '構造化された視覚的に一貫したユーザーインターフェイスの設計', 200.00, 30000.00, 1600.00, NULL, NULL),
(46, 12, 'Intermediate', '中級', 'Build reusable UI components and structured design systems', '再利用可能なUIコンポーネントと構造化設計システムの構築', 'Build reusable UI components.  Define design tokens and variables.  Create cohesive style guides.  Maintain cross platform visual consistency.  Structure component libraries efficiently', '再利用可能なUIコンポーネントの構築\nデザイントークンと変数の定義\n一貫性のあるスタイルガイドの作成\nクロスプラットフォームの視覚的一貫性の維持\nコンポーネントライブラリの効率的な構造', 'Build reusable and scalable design systems', '再利用可能でスケーラブルな設計システムの構築', 450.00, 75000.00, 3600.00, NULL, NULL),
